programs.sol:
"""Approximate a response to light-verb noun complements.

The main negative responses finish expressions such as 'make sense', 'have
access', and 'take care'. Articles, negation and quantity also cue smaller
abstract-noun responses. Modifiers weaken a more distant verb's effect;
capitalized words receive half the English response. A few auxiliary,
recipient, and Chinese/Vietnamese constructions are included too.

Only four previous token fragments are kept; documents and clauses reset them.
The lexicon names familiar expressions, not vocabulary IDs or model weights.
"""
READS = ()

# Familiar noun complements, grouped by approximate response size.
PHRASES = {
    'make': {
        2.2: 'sense mistake mistakes excuses',
        1.8: 'decisions predictions progress choices',
        1.4: 'decision changes difference money effort efforts attempts note impact '
             'connection connections contact adjustments improvements requests edits '
             'recommendations selections announcements contribution contributions '
             'assumptions promises claims plans appearances',
        0.7: 'payment reference way',
    },
    'have': {
        2.4: 'access trouble questions',
        1.8: 'problems issues permission chance difficulty doubts',
        1.2: 'question interest confidence sex fun pleasure blast mercy rights '
             'feelings symptoms intention clue obligation opportunity '
             'opportunities experience effect impact',
        0.7: 'reason reasons time idea choice influence role occasion respect',
    },
    'take': {
        2.0: 'advantage risks effect',
        1.6: 'care steps action pleasure notes pictures',
        1.0: 'interest control responsibility charge look notice ownership '
             'photos photographs calls screenshots inspiration bite chance '
             'opportunity precautions',
        0.4: 'place part time turns',
    },
    'pay': {1.8: 'attention', 0.8: 'tribute respect'},
    'draw': {1.2: 'attention conclusions distinction'},
    'give': {
        1.7: 'chance insight insights access',
        1.0: 'attention rise support credit consent permission notice example '
             'evidence assurances reasons',
        0.5: 'way information advice answer answers instructions confidence',
    },
    'provide': {
        1.8: 'insight insights access',
        1.2: 'feedback evidence advice answers',
        0.9: 'support assistance information examples instructions energy',
    },
    'get': {
        1.8: 'chance access',
        0.6: 'help support look answers ideas updates style data name value',
    },
    'gain': {2.0: 'access insight insights', 1.0: 'confidence support experience'},
    'play': {1.0: 'role part'},
    'ask': {1.6: 'questions', 0.8: 'question'},
    'receive': {1.5: 'email feedback', 0.8: 'support advice comments'},
    'send': {1.2: 'email messages', 0.8: 'message'},
    'need': {0.8: 'help support advice'},
    'lose': {1.3: 'interest confidence control sight'},
    'raise': {1.0: 'questions concerns awareness'},
    'keep': {0.6: 'track pace record'},
}

FORMS = {
    'make': 'make makes making made',
    'have': 'have has having had',
    'take': 'take takes taking took taken',
    'pay': 'pay pays paying paid',
    'draw': 'draw draws drawing drew drawn',
    'give': 'give gives giving gave given',
    'provide': 'provide provides providing provided',
    'get': 'get gets getting got gotten',
    'gain': 'gain gains gaining gained',
    'play': 'play plays playing played',
    'ask': 'ask asks asking asked',
    'receive': 'receive receives receiving received',
    'send': 'send sends sending sent',
    'need': 'need needs needing needed',
    'lose': 'lose loses losing lost',
    'raise': 'raise raises raising raised',
    'keep': 'keep keeps keeping kept',
}

VERBS = {form: root for root, forms in FORMS.items() for form in forms.split()}

OBJECTS = {
    root: {word: strength for strength, words in groups.items()
           for word in words.split()}
    for root, groups in PHRASES.items()
}

# State, opportunity, and communication nouns with a standing response.
STATE_OR_MESSAGE = set(
    'attention questions chance insight insights evidence feedback permission '
    'trouble pleasure'.split()
)
NOUNS = set().union(*(set(objects) for objects in OBJECTS.values()))
NOUNS -= {'sure', 'rid'}
NOUNS |= set(
    'benefit benefits change consequence constraints differences doubt effects '
    'exceptions feeling glimpse hesitation indication interests issue limitation '
    'limitations mention need objection objections power problem proof purpose '
    'purposes regret regrets replacement request result risk signs threats'.split()
)

ARTICLES = {'a', 'an'}

QUANTITY = set('any some much more little few enough many'.split())

POSSESSIVES = set('my your our their his her its'.split())

MODIFIERS = set(
    'great good perfect reasonable significant important informed valuable direct '
    'easy full total special major vital crucial small big additional effective '
    'strategic positive negative practical considerable strong clear better real '
    'further other different same new technical informed financial excellent '
    'certain substantial serious appropriate necessary relevant personal '
    'extra close proper particular suitable business occasional '
    'concrete adequate quick brief deep lasting meaningful'.split()
)

BRIDGES = ARTICLES | QUANTITY | POSSESSIVES | MODIFIERS | {
    'the', 'no', 'us', 'you', 'me', 'them', 'all', 'their', 'most', 'every',
}

CHINESE_ABSTRACT = set(
    '问题 問題 机会 機會 意义 意義 耐心 信心 经验 經驗 兴趣 興趣 '
    '影响 影響 作用 价值 價值 面子 能力 本事 魅力 吸引力 意见 意見 '
    '帮助 幫助 责任 責任 优势 優勢 效果 贡献 貢獻 挑战 挑戰 '
    '影响力 影響力 反应 反應 计划 計劃 义务 義務 疑问 疑問 疑惑 '
    '理由 进展 進展 变化 變化 措 误 誤 趣 限 果 意 权利 權利 动力 動力'.split()
)

NOUN_CUES = {
    **dict.fromkeys(ARTICLES, -0.25),
    **dict.fromkeys(QUANTITY, -0.20),
    **dict.fromkeys(POSSESSIVES, -0.08),
    **dict.fromkeys(MODIFIERS, -0.09),
    'no': -0.70, 'without': -0.70, 'with': -0.32,
}
NOMINAL_SUFFIXES = (
    'tion', 'sion', 'ment', 'ness', 'ity', 'ance', 'ence',
    'tions', 'ments', 'ities',
)


def modifier(word):
    return word in BRIDGES or (
        len(word) > 4 and word.isalpha()
        and word.endswith(('al', 'ive', 'ous', 'ful', 'less', 'ic', 'ary',
                           'able', 'ible', 'ing'))
    )


def verb_complement(previous, noun, generic=False):
    """Find a familiar expression through intervening modifiers/recipients."""
    for distance, word in enumerate(reversed(previous)):
        root = VERBS.get(word)
        if root:
            strength = 0.27 if generic else OBJECTS[root].get(noun)
            if strength is not None:
                return strength * 0.8 ** distance
        if not modifier(word):
            break
    return None


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = [] if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    # Treat an identifier's .method or _object fragment as its ordinary word.
    word = token.strip().lstrip('._').lower()
    prior = previous[-1] if previous else ''
    known_noun = word in NOUNS
    noun_like = known_noun or (
        len(word) > 5 and word.isalpha() and word.endswith(NOMINAL_SUFFIXES)
    )
    value = 0.0
    if known_noun:
        value = -0.017 - 0.295 * (word in STATE_OR_MESSAGE)
        value += NOUN_CUES.get(prior, 0.0)
    if noun_like:
        strength = verb_complement(previous, word) if known_noun else None
        if strength is not None:
            value -= 0.93 * strength
        else:
            value -= verb_complement(previous, word, generic=True) or 0.0
            if not known_noun:
                if prior in {'no', 'without'}:
                    value -= 0.27
                elif prior in ARTICLES:
                    value -= 0.037

    # Small grammatical partners of the same light verbs.
    root = VERBS.get(prior)
    if word == 'sure' and root == 'make':
        value -= 0.27
    if word == 'rid' and root == 'get':
        value -= 0.81
    if word == 'been' and prior in {'have', 'has', 'had'}:
        value -= 0.09
    if word in {'you', 'us', 'me', 'them', 'him', 'her'}:
        if root in {'give', 'provide', 'send'}:
            value += 0.26
    if word == 'thể' and prior == 'có':  # Vietnamese 'can'.
        value -= 0.66
    if token.strip()[:1].isupper():
        value *= 0.5
    if previous and word in CHINESE_ABSTRACT:
        value -= 0.16
        if prior.endswith(('有', '无', '無', '有任何')):
            value -= 1.38

    if word:
        previous = (previous + [word])[-4:]
    if '\n' in token or token.strip() in {'.', ';', '!', '?', '...'}:
        previous = []
    return (doc, previous), float(value)

programs.luna:
"""Approximate sparse responses to odd whitespace and repeated code marks."""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    was_tab = carry is not None and carry[0] == document and carry[1]
    mark = token.rstrip('\r\n')

    if token == '---':
        value = 0.24
    elif token in (' \\\n', '\\\n'):
        value = -0.45
    elif mark and all(char == '\u00a0' for char in mark):
        value = -1.55 if len(mark) >= 3 else -0.7
    elif token and all(char == '\t' for char in token) and (len(token) >= 2 or was_tab):
        value = -0.57
    elif mark and all(char == '`' for char in mark) and len(mark) >= 2:
        value = -0.5
    elif token == '<<':
        value = -0.15
    elif mark and len(mark) >= 3 and len(set(mark)) == 1 and mark[0] == '*':
        value = -0.15
    elif (mark and len(mark) >= 7 and len(set(mark)) == 1 and mark[0] == '-') or (
        mark and len(mark) >= 4 and token.endswith(('\n', '\r'))
        and len(set(mark)) == 1 and mark[0] == '-'
    ):
        value = -1.7
    elif mark and len(mark) >= 7 and len(set(mark)) == 1 and mark[0] == '=':
        value = -1.7
    else:
        value = 0.0

    return (document, token.endswith('\t')), float(value)

"""Predict negative activations for change verbs and their close equivalents."""
READS = ()

CHANGE_ACTIONS = (
    "replace",
    "convert",
    "switch",
    "transfer",
    "alternate",
)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous_doc, word = carry if carry is not None else (doc, "")
    if doc != previous_doc:
        word = ""

    for char in token:
        if char.isalpha():
            word += char.lower()
        else:
            word = ""

    value = 0.0
    if word.startswith("chang"):
        value = -3.6
    elif word.startswith(CHANGE_ACTIONS):
        value = -1.1
    elif word.startswith("range"):
        value = -0.6
    elif "换" in token:
        value = -5.0
    elif "更改" in token:
        value = -1.6
    elif "变为" in token:
        value = -0.5
    elif "환" in token:
        value = -1.0
    return (doc, word[-20:]), value

programs.sol:
"""Opening-of-document separator response.

Give punctuation, whitespace boundaries and "and" fitted opening pulses,
fading with document token age and repeated separator kinds. Scale them
using the preceding token's length, spacing, case, digit ending and role
name. Ordinary words get small grammatical baselines; a user label after a
chat-start marker gets its own curve. Document changes reset the state;
the first token has a separate value. Coarse families omit finer lexical
and punctuation distinctions.
"""
import math

READS = ()


def separator(text):
    s = text.strip()
    if not s:
        if '\n' in text or '\r' in text:
            return 'paragraph' if text.count('\n') > 1 else 'line'
        return 'space' if len(text) == 1 else 'indent'
    if s.lower() == 'and':
        return 'and'
    if any(c.isalnum() or c == '\ufffd' for c in s):
        return None
    if '。' in s:
        return 'CJK stop'
    if '.' in s and s.count('.') == 1 and not text.startswith(' '):
        return 'stop'
    if '?' in s or '？' in s:
        return 'question'
    if '!' in s or '！' in s:
        return 'exclamation'
    if any(c in ',，،;；' for c in s):
        return 'comma'
    if ':' in s or '：' in s:
        return 'colon'
    if '\n' in text:
        return 'line punctuation'
    if any(c in ')]}）】' for c in s):
        return 'close bracket'
    if s in {'(', '[', '{'} and text.startswith(' '):
        return 'open bracket'
    return 'other punctuation'


# Background; boosts with 2-, 15-, 100-token decay scales; first token.
CURVES = {
    'CJK stop': (-0.150, 0.407, 3.407, 0.819, 0.687),
    'and': (-0.037, 0.784, 0.427, -0.027, 0.123),
    'close bracket': (-0.019, -0.138, 0.601, 0.085, -0.087),
    'colon': (-0.030, 0.425, 0.759, 0.116, 0.066),
    'comma': (-0.039, 1.816, 1.133, 0.267, -0.183),
    'exclamation': (-0.041, 0.095, 1.164, 0.204, 0.017),
    'indent': (-0.026, -0.208, 0.685, 0.313, 0.360),
    'line': (-0.016, 1.519, 1.593, 0.028, -0.086),
    'line punctuation': (0.015, -0.414, 1.041, -0.046, -0.064),
    'open bracket': (-0.021, 0.745, 0.458, 0.029, -0.142),
    'other punctuation': (-0.012, 0.078, 0.406, 0.007, 0.094),
    'paragraph': (-0.030, 0.588, 1.176, 0.041, -0.122),
    'question': (-0.028, 0.335, 1.838, 0.359, 0.320),
    'space': (-0.029, 0.198, 0.694, 0.127, 0.141),
    'stop': (-0.040, 0.232, 2.031, 0.990, 0.226),
}


def ordinary(text, age):
    word = text.strip().lower()
    if word in {'the', 'a', 'an'}:
        floor, opening = 0.036, -0.15
    elif word in {'of', 'to', 'in', 'for', 'with', 'from', 'by', 'on', 'at'}:
        floor, opening = 0.030, -0.16
    elif word in {'is', 'are', 'was', 'were', 'be', 'been', 'being', 'am'}:
        floor, opening = 0.016, -0.10
    else:
        floor, opening = 0.008, -0.035
    return floor + opening * math.exp(-age / 80)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        age, previous, counts = 0, '', {}
    else:
        _, old_age, previous, counts = carry
        age = old_age + 1
    text = prefix.token_strings[-1]
    kind = separator(text)
    if kind is None:
        if text == 'user' and previous == '<|im_start|>':
            value = (0.038 + 0.593 * math.exp(-age / 8)
                     - 0.178 * math.exp(-age / 25)
                     + 0.168 * math.exp(-age / 80))
        else:
            value = ordinary(text, age) if age else 0.0
    else:
        floor, onset, sentence, paragraph, first = CURVES[kind]
        seen = counts.get(kind, 0)
        if age == 0:
            value = first
        else:
            word = previous.strip()
            weight = math.exp(0.035 * (min(len(word), 10) - 5))
            if word[-1:].isdigit():
                weight *= 0.53
            if word.isalpha() and len(word) == 1:
                weight *= 0.89
            if previous.startswith(' '):
                weight *= 1.14
            if word.isupper():
                weight *= 0.77
            if previous in {'user', 'assistant', 'system'}:
                weight *= 2.0
            weight *= (1 - math.exp(-age)) / math.sqrt(1 + seen)
            value = floor + weight * (
                onset * math.exp(-age / 2) + sentence * math.exp(-age / 15)
                + paragraph * math.exp(-age / 100))
        counts[kind] = seen + 1
    return (doc, age, text, counts), float(value)

programs.luna:
"""Approximate early-context and punctuation-related activation bumps."""

READS = ()


def step(carry, prefix, upstream):
    doc_id = prefix.document_ids[-1]
    if carry is None or carry[0] != doc_id:
        doc_position = 0
    else:
        doc_position = carry[1] + 1

    token = prefix.token_strings[-1]
    same_document = len(prefix) > 1 and prefix.document_ids[-2] == doc_id
    previous = prefix.token_strings[-2] if same_document else ""
    trimmed = token.rstrip()
    previous_text = previous.rstrip()
    value = -0.003

    # Add a small bump during the first few positions after a context reset.
    if 1 <= doc_position <= 17:
        value += 0.12

    if "." in token:
        value += 0.065
    if "," in token:
        value += 0.04
    if any(mark in token for mark in "?!？！"):
        value += 0.063
    if "\n" in token:
        value += 0.032
    if token.isspace():
        value -= 0.021
    if "<|" in token:
        value -= 0.04
    if "<|" in previous:
        value += 0.044
    if trimmed and trimmed[-1] in ".。" and previous_text:
        if previous_text[-1].isalpha():
            value += 0.08
        if "\n" in previous:
            value += 0.05

    return (doc_id, doc_position), value

programs.haiku:
"""Layer-0 MLP down-projection component 5764, as a rule-based predictor.

The component is a "showing / demonstrating / asking-how" feature. It goes
negative on the word that introduces what is being shown, proved, checked or
asked about, and is close to zero elsewhere. Predictions are negative.

* "how": strongest when it follows a showing or seeing verb ("see how",
  "shows how", "illustrates how", "understand how"), weaker otherwise;
* the verbs of demonstrating and verifying themselves ("demonstrate",
  "illustrates", "verify", "prove") and, more weakly, "show/shows/shown";
* "why" and "what" as question words;
* "that", "of", "the" right after a showing or evidence word
  ("shown that", "show that", "example of", "instance of", "evidence of").

Everything else predicts 0.
"""

READS = ()

DEMO_VERBS = {"demonstrate", "demonstrates", "demonstrated", "illustrate", "illustrates",
              "verify", "verifies", "prove", "proves", "proof"}
SHOW_VERBS = {"show", "shows", "showed", "shown", "showing", "see", "confirm", "confirms"}
# words after which "that", "of", "the", "how" introduce the thing shown or proved
SHOWN_BEFORE = SHOW_VERBS | DEMO_VERBS | {"example", "examples", "instance", "evidence",
                                          "understand"}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1].strip().lower()
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip().lower() if same_doc else ""
    after_show = prev in SHOWN_BEFORE
    if cur == "how":
        return None, -2.5 if after_show else -1.0
    if cur in DEMO_VERBS:
        return None, -1.5
    if cur in SHOW_VERBS:
        return None, -0.5
    if cur == "why":
        return None, -0.5
    if cur == "what":
        return None, -0.25
    if after_show:
        if cur in ("that", "of"):
            return None, -1.0
        if cur == "the":
            return None, -0.5
    return None, 0.0

programs.sol:
"""A soft detector of vowels meeting across subword-token boundaries.

The strongest junction is e + u, followed by e + o and e + i.
Other vowel junctions and certain e-consonant junctions are weaker.
Long fragments and a lowercase-to-uppercase boundary reduce the response.
All comparisons concern adjacent tokens in the same document, without
intervening whitespace; this is not a general word- or topic-detector.
"""
import math
import unicodedata

READS = ()
CYRILLIC_VOWELS = str.maketrans('аеёиоуыэюя', 'aeeiouieua')
E_VOWEL_GAIN = {'a': .47, 'e': .40, 'i': 1.58, 'o': 2.39, 'u': 3.36}


def base_letter(char):
    unaccented = unicodedata.normalize('NFD', char.lower())[:1]
    return unaccented.translate(CYRILLIC_VOWELS)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    value = 0.0
    if previous and token:
        left = base_letter(previous[-1])
        right = base_letter(token[0])
        if left in 'aeiou' and left:
            if left == 'e':
                value = E_VOWEL_GAIN.get(right, 0.0)
                if token[0].lower() in 'bpvбпв':
                    value = .83
                elif token[0].lower() in 'lhлх':
                    value = .42
                elif token[0].lower() in 'cktкц':
                    value = .26
            elif right in 'aeiou' and right:
                value = .50
                if left in 'ao' and right == 'e':
                    value = .85
                elif left == 'a' and right in 'au':
                    value = .70
                elif left == 'i' and right in 'aei':
                    value = .25
            if value:
                before = len(previous.strip())
                after = len(token.strip())
                value *= (1.18 if before == 1
                          else max(.18, 1 - .12*max(0, before - 2)))
                value *= .84 if after == 1 else math.exp(-.24*max(0, after - 2))
                if previous[-1].isupper():
                    value *= .89 if token[0].isupper() else 1.26
                elif token[0].isupper():
                    value *= .31
    return (doc, token), float(value)

programs.luna:
"""Predict a small pulse when a letter fragment continues a word already underway."""
import unicodedata

READS = ()


def is_letter(char):
    return bool(char) and unicodedata.category(char).startswith("L")


def step(carry, prefix, upstream):
    if len(prefix.token_ids) < 2:
        return None, 0.0
    if prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0
    current = prefix.token_strings[-1]
    previous = prefix.token_strings[-2]
    if (current and not current[0].isspace() and is_letter(current[0])
            and previous and is_letter(previous[-1])):
        return None, 0.03
    return None, 0.0

programs.sol:
"""A token-spelling approximation to a pattern-vocabulary detector.

English 'pattern(s)', Chinese 模式 and Japanese パターン get large values.
Related model, mode, format, template, regular-expression, trend and
appearance words get smaller values. Some Chinese pattern words and
characters are included too. Case, punctuation and compound length adjust
these strengths. Document-local state recognizes spelling continuations
and 'pattern(s) of/for'; all other positions are predicted as zero.
This does not detect arbitrary abstract patterns or reproduce every weak
background activation.
"""
READS = ()


def lexical(text):
    word = text.strip().strip('._-/\\(=:\"\'').lower()
    if word == 'pattern':
        value = 6.6
        if text.startswith('(') or text.startswith('.P'):
            value = 5.5
        if text.strip().isupper():
            value = 5.0
        return word, value
    if word == 'patterns':
        return word, 6.8 if text.strip().startswith('Patterns') else 5.7
    if word in ('model', 'models', 'mode', 'modes'):
        if word.endswith('s'):
            return word, 0.73
        return word, 1.20 if word == 'mode' else 1.0
    if word in ('format', 'formats', 'template', 'templates'):
        return word, 0.60 if word.endswith('s') else 0.80
    if word in ('regex', 'regexp'):
        return word, 1.0
    if word in ('fmt', 'grep'):
        return word, 0.52
    if word in ('prototype', 'paradigm', 'signature', 'signatures',
                'motif', 'motifs'):
        return word, 0.68
    if word in ('trend', 'trends', 'fashion', 'rhythm', 'rhythms'):
        return word, 0.90
    if word == 'pat':
        return word, 0.72
    if word in ('patt', 'patter'):
        return word, 1.5 if word == 'patt' else 3.5
    if word in ('lifestyle', 'hairstyle', 'hairstyles'):
        return word, 0.48 if word == 'lifestyle' else 1.10
    if word.endswith('模式'):
        return word, max(1.5, 6.0 - 1.6 * (len(word) - 2))
    if word == 'パターン':
        return word, 5.2
    if word == '图案':
        return word, 3.5
    if word in ('花纹', '紋'):
        return word, 1.8
    if word in ('模型', '模板', '格式', '趋势', '格局', '发型'):
        return word, 1.0
    if word in ('式', '范', '範'):
        return word, 0.9
    if word in ('型', '模', '款', '款式', '方式',
                '形式', '习惯', '的习惯', '的方式', '的形式'):
        return word, 0.65
    if word == '纹':
        return word, 2.7
    if word == '指纹':
        return word, 1.3
    return word, 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    text = prefix.token_strings[-1]
    word, value = lexical(text)
    if word == 'of':
        if previous == 'pattern':
            value = 3.0
        elif previous == 'patterns':
            value = 2.1
        elif previous in ('model', 'models', 'mode', 'modes', 'trend'):
            value = 0.35
    if previous == 'pattern' and text in ('ed', 's'):
        value = 3.2 if text == 'ed' else 3.5
        if text == 's':
            word = 'patterns'
    if previous == 'patter' and text == 'ning':
        value = 2.4
    if word == 'for' and previous in ('pattern', 'patterns'):
        value = 0.6 if previous == 'pattern' else 0.3
    if previous in ('pattern', 'patterns') and text == '.compile':
        value = 0.8
    if word == 'attern' and previous.endswith('p'):
        word = 'pattern'
        value = 6.9 if text.isupper() else 5.7
    return (doc, word), float(value)

programs.haiku:
"""Layer-0 MLP component 5768: a "pattern" word detector.

In plain terms, the component reads the current word and the one before it:
- The word "pattern" in any form (" pattern", "Pattern", " patterns", "_pattern", "(pattern",
  and the Chinese 模式) gives about 6.2, its strongest response.
- " of" right after a pattern word ("pattern of") gives about 2.7.
- A family of related words (model, mode, format, template, regex, trend, fashion, grep,
  fmt, and the Chinese 模型, 模板, 格式, 式, 趋势) gives about 1.0, and about 0.6 for the
  looser group (grep, fmt, pat, 型, 方式, 时尚, 潮流, paradigm, prototype). " of" right after
  a related word gives about 0.3.
- Every other token gives 0. The rest of the component's small variance (under 0.3 in
  magnitude, spread over common tokens) is not captured.
"""

import re

READS = ()

PATTERN_VALUE = 6.2
PATTERN_OF_VALUE = 2.7
RELATED_VALUE = 1.0
RELATED_OF_VALUE = 0.3
LOOSE_VALUE = 0.6

RELATED_WORDS = {
    "model", "models", "mode", "modes", "format", "formats", "template", "templates",
    "regex", "regexp", "trend", "trends", "fashion", "hairstyle", "hairstyles",
    "模型", "模板", "格式", "式", "趋势", "模特",
}
LOOSE_WORDS = {
    "fmt", "grep", "pat", "型", "方式", "时尚", "潮流", "paradigm", "prototype",
    "findall", "matcher",
}


def _word(token):
    """The token's letters and digits, lowercased: " _model" -> "model", " 模式" -> "模式"."""
    return "".join(re.findall(r"[a-z0-9一-鿿]+", token.lower()))


def _is_pattern(word):
    return "pattern" in word or word in ("模式", "attern")


def _is_related(word):
    return word in RELATED_WORDS or word.endswith("model") or word.endswith("format")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = _word(token)
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    previous = _word(prefix.token_strings[-2]) if same_doc else ""
    if _is_pattern(word):
        return carry, PATTERN_VALUE
    if token.strip() == "of" and _is_pattern(previous):
        return carry, PATTERN_OF_VALUE
    if token.strip() == "of" and _is_related(previous):
        return carry, RELATED_OF_VALUE
    if _is_related(word):
        return carry, RELATED_VALUE
    if word in LOOSE_WORDS:
        return carry, LOOSE_VALUE
    return carry, 0.0

programs.sol:
"""A spelling-based condition/time signal, not a semantic parser.

If, when, current, and a few translations give moderate positive responses.
The isolated Chinese/Japanese character 当/當 gives a very large response,
even when it does not mean 'when'. Compounds usually respond less. Indented
code and 'else if' strengthen if; concessive and question phrases weaken it.
The Korean syllable 당 is positive regardless of its meaning.
"""
import re

READS = ()
IF_WORDS = {'wenn', 'если', 'nếu', 'إذا', '若', '若是', '一旦'}
WHEN_WORDS = {
    'когда', 'cuando', 'quando', 'lorsque', 'khi', 'när', 'når'
}
TIME_WORDS = {'当时', '當時', '当年', '当今', '当下', '当代', '当初'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    line = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lstrip('.(_-\"“—').lower()
    value = 0.0
    if lower == 'if':
        value = 1.0 if word.endswith('if') else 1.15
        if word.startswith(('.', '_', '-')):
            value = 1.8
        elif '\t' in token or re.search(r'\belse\s*$', line):
            value = 1.72
        elif word == 'if' and line and line.isspace():
            value = 1.56
        elif re.search(r'\beven\s*$', line, re.I):
            value = 0.35
        elif re.search(r'\b(as|only)\s*$', line, re.I):
            value = 0.46
        elif re.search(r'\b(see|ask\w*|wonder\w*)\s*$', line, re.I):
            value = 0.55
        elif word == 'if' and not line and not token.startswith(' '):
            value = 1.42
    elif lower in {'#if', '#ifdef', '#ifndef'}:
        value = 0.9 if lower == '#ifndef' else 1.6
    elif lower in {'when', 'whenever', 'elif', 'elseif'}:
        value = 1.05 if lower == 'when' else 1.3
    elif lower == 'unless':
        value = 0.52
    elif lower in {'current', 'currents', 'currently'} or word == '电流':
        value = 0.33 if lower == 'currently' else 0.95
    elif word in {'当', '當'}:
        value = 5.2 if token.startswith(' ') else 6.0
    elif (word.startswith(('当', '當'))
          and word[1:].startswith(tuple('我你他她它'))):
        value = 5.5
    elif word in TIME_WORDS:
        value = 1.7
    elif word.startswith(('当', '當')):
        if word in {'当然', '當然', '当たり前'}:
            value = 0.3
        else:
            value = 2.7 / (len(word) - 1) ** 0.5
    elif word == '당':
        value = 4.1 if token.startswith(' ') else 3.1
    elif word.startswith('如果') or lower == 'eğer':
        value = 1.1
    elif lower in IF_WORDS:
        value = 0.7
    elif lower in WHEN_WORDS:
        value = 0.85
    line = (line + token.replace('\\n', '\n')).rsplit('\n', 1)[-1][-160:]
    return (doc, line), value

