programs.sol:
"""A lexical 'right/correct' detector, not a test of truth.

Right is strongest: directions, judgments, and rights all count, as does
LaTeX's right delimiter. Correct/wrong and related judgments are weaker.
Some translations and spelling echoes count too. Recent left dampens right;
'right of' and split '-ly' endings retain a response. Everything else is zero.
The numbers approximate word families, omitting weak vocabulary-specific detail.
"""
import math

READS = ()
JUDGMENTS = {
    'correctly': -3.0, 'wrong': -3.0, 'wrongly': -2.7,
    'incorrect': -2.2, 'incorrectly': -2.3, 'correctness': -1.9,
    'correction': -1.0, 'corrected': -1.6, 'mistake': -1.1,
    'proper': -0.95, 'properly': -1.35, 'appropriate': -1.25,
    'appropriately': -1.3, 'perfect': -0.75, 'perfectly': -0.75,
    'okay': -1.2, 'alright': -2.8,
}
RELATED = {
    'copyright': -1.2, 'permission': -0.65, 'entitlement': -1.2,
    'rightly': -3.5, 'rightful': -2.2, 'rightfully': -2.2,
    'righteous': -1.8, 'righteousness': -2.2,
    'straight': -0.95, 'bottom': -0.6, 'rhs': -1.7,
    'wright': -3.3, 'bright': -1.0, 'ight': -0.75, 'orrect': -2.65,
}
TRANSLATIONS = {
    '右': -6.35, '对': -0.7, '對': -0.7, '左': -1.15,
    '正确': -2.3, '正確': -2.5, '正确的': -3.25,
    '权': -1.7, '權': -1.5, '权利': -3.4, '權利': -3.2,
    'право': -2.0, 'права': -2.2, 'правильно': -2.3,
    'richtig': -2.1, 'droits': -2.1, 'derechos': -2.85,
    'đúng': -2.45, 'phải': -1.1,
}
WORDS = JUDGMENTS | RELATED | TRANSLATIONS


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 10000, '', 0.0)
    _, distance, previous, previous_value = carry
    distance += 1
    token = prefix.token_strings[-1]
    spelling = token.strip()
    letters = spelling.lstrip('_.-([,:/')
    word = letters.lower()
    spaced = token[:1].isspace()
    capital = letters[:1].isupper()
    before = previous.strip().lower()
    value = WORDS.get(word, 0.0)
    if word == 'right':
        if token == 'right' and previous.endswith('\\'):
            value = -4.15 + 1.05 * math.exp(-distance / 20.0)
        else:
            value = -5.7 if token == 'right' else -6.65
            if spelling.startswith('['):
                value = -3.5
            elif spelling.startswith('('):
                value = -4.8
            elif spelling.startswith(('.', '_', ',', ':', '/')):
                value = -5.9
            value += 1.8 * math.exp(-distance / 12.0)
            if spaced and before == 'own':
                value += 1.0
    elif word == 'rights':
        value = -4.45
    elif word == 'correct':
        value = -3.5 if spaced or capital else -2.9
        if spaced and before == 'the':
            value -= 0.25
    elif word == 'left':
        value = -1.1 if capital else -0.9 if spaced else -0.7
    elif word == 'прав':
        value = -2.35 if spaced else -1.15
    if word == 'of' and before in {'right', 'rights'}:
        value = -1.45
    if token == 'ly':
        value = 0.8 * previous_value if previous_value < -0.5 else -0.1
    distance = 0 if word in {'left', '左'} else distance
    return (doc, distance, token, value), float(value)

