"""Approximate the component's negative responses to right/correctness words.

The strongest response is to “right”; legal rights, correctness terms, and
weaker direction or propriety words get smaller responses. No context is read.
"""
READS = ()

RIGHT = {"right"}
LEGAL_RIGHTS = {"rights"}
RIGHT_ALIASES = {"rhs", "прав", "sağ", "recht"}
CORRECT = {"correct", "wrong"}
PARTS = {"orrect", "incorrect", "correctly", "incorrectly"}
RELATED = {
    "correctness", "properly", "improperly", "appropriate", "perfect",
    "perfectly", "straight", "straightforward", "left", "bottom", "okay",
    "falsely", "permission", "rect", "copyright", "版权",
}
CHINESE = {"對", "对", "錯", "错"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().strip(".,;:!?()[]{}\"'`").casefold()
    if word in RIGHT:
        value = -6.0
    elif word in LEGAL_RIGHTS:
