programs.sol:
"""Approximate detector of numbers naming items: Chapter 1, Figure 2, Phase II.

Label nouns give a negative response at the first numeral and a smaller one
at a standalone separating space. Dates, versions and identifier suffixes
are weaker cases. Continuing digits are nearly silent. This is a lexical
approximation, not a general parser of whether a number is an identifier.
"""
import re

READS = ()

# Empirical strengths: (first numeral, separating space, label nouns).
LABEL_GROUPS = (
    (4.8, 2.7, 'chapter part volume episode phase step lesson lecture '
     'assignment homework practice exam tutorial'),
    (4.0, 2.35, 'section article grade grades day week tier district suite '
     'type league lab month'),
    (3.5, 1.7, 'table rule level route highway box unit class season stage '
     'division annex experiment scene station series'),
    (2.9, 1.6, 'figure case example question problem group theorem lemma '
     'proposition algorithm claim verse option module exercise requirement '
     'algebra appendix paragraph directive exhibit'),
    (2.3, 1.25, 'test code equation number page line year version windows '
     'base form node row term degree channel zone graph item act title '
     'chromosome exon formula radio'),
    (1.7, 0.85, 'index position column sheet size block set issue point '
     'element device member area layer region field method solution round '
     'model species category kind view property parameter attribute variable'),
)
LABELS = {word: (number, space)
          for number, space, words in LABEL_GROUPS for word in words.split()}
for word, (number, space) in list(LABELS.items()):
    if not word.endswith('s'):
        LABELS[word + 's'] = (number * 0.8, space * 0.8)

for number, space, words in (
    (3.6, 1.9, 'playstation iphone ios phone os xbox'),
    (4.1, 0.7, 'war'),
    (2.65, 0.78, 'fig figs figures'),
    (1.2, 0.9, 'no nr'),
    (3.7, 1.4, 'vol'),
    (1.85, 0.48, 'january february march april may june july august '
     'september october november december'),
    (1.35, 0.18, 'jan feb mar apr jun jul aug sep oct nov dec'),
):
    LABELS.update({word: (number, space) for word in words.split()})

FUNCTION_WORDS = set(('a an the and or but of in on at to for from with '
                      'is are was were be by as than then').split())
NUMBER_WORDS = set(('zero one two three four five six seven eight nine '
                    'ten eleven twelve').split())
ROMAN = re.compile(r'[IVX]+$')
LAST_WORD = re.compile(r'([A-Z]?[a-z]+|[A-Z]+)\.?[^\S\r\n]*$')
ABBREVIATIONS = {'fig', 'figs', 'no', 'nr', 'vol'}


def label_profile(tail):
    """Read a trailing word, including the last word of a camelCase name."""
    match = LAST_WORD.search(tail)
    word = match.group(1).lower() if match else ''
    if match and tail[match.end(1):].startswith('.'):
        if word not in ABBREVIATIONS:
            word = ''
    number, space = LABELS.get(word, (0.0, 0.0))

    # Reference signs, East Asian ordinals, figure/article labels and dates.
    end = tail.rstrip()
    if end.endswith(('§', '№')):
        number, space = 3.2, 1.8
    elif end.endswith('#') and not end.endswith(('##', '\n#')):
        number, space = 1.8, 0.2
    elif end.endswith(('第', '제')):
        number, space = 3.1, 1.5
    elif end.endswith('月'):
        number, space = 2.4, 0.5
    elif end.endswith(('表', '图', '圖', '章', '条', '條', '제목')):
        number, space = 3.4, 1.5
    elif end.endswith('年'):
        number, space = 0.85, 0.1

    if match:
        gap = tail[match.end(1):]
        if len(gap) > 1 and gap.isspace():
            number *= 0.25
            space *= 0.25
    capitalized = bool(match and match.group(1)[0].isupper())
    return word, number, space, capitalized


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, previous = '', ''
    else:
        _, tail, previous = carry
    token = prefix.token_strings[-1]
    s = token.strip()
    state = (doc, (tail + token)[-48:], token)

    decimal = bool(s and s.isdecimal())
    spelled = bool(s and (s.lower() in NUMBER_WORDS
                         or s in '零一二三四五六七八九十'))
    roman = bool(s and token.startswith(' ') and ROMAN.fullmatch(s))
    letter = (len(s) == 1 and s.isascii() and s.isupper()
              and token.startswith(' '))
    if not (token == ' ' or decimal or spelled or roman or letter):
        return state, 0.0

    word, number, space, capitalized = label_profile(tail)
    content_word = bool(word and word not in FUNCTION_WORDS)
    value = 0.0
    if token == ' ':
        value = -space if number else (-0.16 if content_word else 0.0)
    elif decimal:
        if previous and previous[-1].isdecimal():
            value = 0.025
        elif number:
            scale = 0.78 if s == '0' else (1.1 if s == '1' else 1.0)
            value = -number * scale
        elif tail.endswith('_'):
            value = -0.5
        elif tail.endswith('-'):
            value = -0.3
        elif content_word:
            strength = 0.6 if capitalized else (
                0.3 if tail[-1].isspace() else 0.5)
            value = -strength * (0.5 if s == '0' else 1.0)
        else:
            value = 0.025
    elif spelled:
        value = -1.1 * number if number else (
            0.15 if word in FUNCTION_WORDS else 0.05)
        if word == 'number':
            value = -5.2
        elif word == 'formula':
            value = -6.0
    elif roman and (len(s) > 1 or s == 'I' or number):
        value = -1.15 * number if number else (-0.02 if s == 'I' else -1.0)
        if s == 'I' and word in ('day', 'week', 'month', 'year', 'lesson'):
            value *= 0.25
    elif letter:
        if number:
            value = -number * (1.2 if word == 'appendix' else 0.5)
        elif content_word:
            value = -0.1
    return state, float(value)

programs.haiku:
"""Layer-0 MLP unit 5771 (down_proj): a number that names an item in a title or label is negative.

Examples: "Section 3", "Table 2", "FIG. 8", "§ 1", "Test 3", "Part II", "Phase II", "Route 3",
"Grade 7", "Windows 8", and dates such as "March 5". The strongest response is on the number
(or Roman numeral, capital letter, or number word) right after a word that introduces numbered
items (section, table, figure, chapter, part, page, example): about -3. After other label words
(test, code, number, line, version, months, and series names like phase, volume, level, season,
route): about -2. After any other capitalised word: about -0.7. After lowercase words, running
text, list words and punctuation such as ", 2001": about 0. The space token that comes just before
such a number is about half as negative as the number itself. Everything else is 0.
"""
READS = ()

# Words that introduce a numbered item: strongest response.
STRONG = {"section", "chapter", "table", "figure", "fig", "figs", "§", "part", "example", "page"}
# Other label words and series names: medium response.
MEDIUM = {"test", "code", "number", "rule", "case", "line", "lines", "equation", "version",
          "algorithm", "verse", "item", "step", "question", "problem", "月", "day"}
SERIES = {"phase", "volume", "vol", "type", "level", "season", "route", "zone", "league", "series",
          "round", "stage", "grade", "episode", "article", "option", "division", "class", "unit",
          "group", "book", "act", "scene", "lesson", "exercise", "edition", "issue",
          "no", "generation", "tier", "track", "game", "lap", "set", "nr"}
MONTHS = {"january", "february", "march", "april", "may", "june", "july", "august",
          "september", "october", "november", "december"}
NUMBER_WORDS = {"one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten"}


def label_strength(word):
    """How strongly the word before a label number pulls it negative (0 = not a label word)."""
    w = word.strip().lower()
    if w in STRONG:
        return 3.0
    if w in MEDIUM or w in MONTHS or w in SERIES:
        return 2.0
    if word.strip()[:1].isupper():
        return 0.7
    return 0.0


def is_label_token(s):
    """A digit, Roman numeral or capital letter (or number word): a possible label."""
    s = s.strip()
    return s.isdigit() or (s.isupper() and len(s) <= 4 and s.isalpha()) or s.lower() in NUMBER_WORDS


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    docs = prefix.document_ids
    cur = toks[-1]
    if len(toks) < 2 or docs[-2] != docs[-1]:
        return None, 0.0
    if cur.strip() == "":
        # A space: negative in proportion to the word before it, half as strong.
        word = toks[-2]
        if word.strip() == "." and len(toks) >= 3:
            word = toks[-3]  # "FIG. 8": look past the abbreviation's full stop
        return None, -0.5 * label_strength(word)
    if is_label_token(cur) and not is_label_token(toks[-2]):
        if toks[-2].strip() == "":
            # the label follows a space: the word before the space decides
            if len(toks) < 3 or docs[-3] != docs[-1]:
                return None, 0.0
            word = toks[-3]
            if word.strip() == "." and len(toks) >= 4:
                word = toks[-4]
            return None, -label_strength(word)
        if toks[-2].strip() == ".":
            return None, 0.0
        # no space: "§3", "#2", "Windows8"
        return None, -label_strength(toks[-2])
    return None, 0.0

programs.sol:
"""A spelling detector for 'base' and weaker foundation-related vocabulary.

Literal 'base' is strongest; casing and leading punctuation adjust its score.
Derivatives, fragments, common/core/foundation words, and listed non-English
base/root forms get smaller positive scores. A fraction of the local response
carries onto an immediately following 'of' or 'upon', within a document only.
Other tokens get zero. This does not resolve meanings or model weak unrelated
activations.
"""
import string

READS = ()


def lexical_response(token):
    spelling = token.strip().lstrip(string.punctuation)
    word = spelling.lower()
    if word == 'base':
        # Typography separates prose roots from code-name fragments.
        upper = spelling[:1].isupper()
        if token.startswith('.'):
            return 4.2 if spelling.isupper() else 5.8 if upper else 7.2
        if token.startswith(('\\', '<')):
            return 4.5
        if token.startswith('('):
            return 5.9 if upper else 4.7
        if token.startswith(('/', '-')):
            return 6.7
        if token.startswith('_'):
            return 6.1
        if token[:1].isspace():
            return 6.4 if upper else 5.8
        return 6.9 if upper else 6.3
    if word == 'bases':
        return 3.5 if token[:1].isspace() else 4.5
    if word == 'based':
        return 1.9 if token[:1] in '-_' else 1.6
    if word in {'basal', 'firebase'}:
        return 1.65
    if word in {'basic', 'basics', 'basis', 'baseline'}:
        return 1.25
    if word == 'baseball':
        return 2.0
    if word.startswith('base') and len(spelling) > 4:
        return 2.1 if spelling[4].isupper() else 0.9
    if word in {'database', 'databases', 'atabases'}:
        return 0.85
    if word in {'bas', 'ase', 'ases', 'ibase'}:
        if word == 'ibase':
            return 4.2
        return 1.3 if word == 'bas' else 0.75
    if word == 'core':
        if token.startswith('/'):
            return 1.5
        return 1.25 if token.startswith('-') else 0.9
    if word in {'common', 'commonly', 'commonwealth'}:
        return 1.2 if token[:1] in './-' else 0.85
    if word in {'foundation', 'foundations', 'foundational'}:
        return 1.45
