import string

READS = ()

# Word families, not a vocabulary-id lookup. Earlier rules take precedence.
FAMILIES = (
    (0.05, ('describ', 'descrip', 'cross', 'across', 'crease', 'democra',
            'discr', 'subscr', 'encrypt', 'microsoft', 'javascript',
            'typescript', 'manuscript', 'aircraft', 'prescri')),
    (0.6, ('credent', 'credib', 'creatur', 'cream', 'secretary',
           'crop', 'crow', 'screw')),
    (1.0, ('criteria', 'critiq', 'critici', 'critics', 'crucial')),
    (1.6, ('creat', 'credit', 'crisis', 'crises', 'crude', 'macro')),
    (2.2, ('critical', 'crime', 'criminal', 'cryst', 'crack', 'crash', 'crate')),
)


def response(token):
    if token == '\r':
        return 0.85  # CR is also the conventional carriage-return abbreviation.
    word = token.strip().strip(string.punctuation).lower()
    if 'cr' in word:
        if word == 'cr':
            return 4.8
        if word in {'scr', 'acr', 'ocr'}:
            return 3.3
        for value, stems in FAMILIES:
            if any(stem in word for stem in stems):
                return value if len(word) <= 12 else value * 0.25
        if word.startswith('cr') and len(word) <= 4:
            return 2.0
        return 0.9
    if word in {'кр', 'кра', 'クリ', 'คร'}:
        return 2.8  # Cyrillic, Japanese and Thai cr/kr-like fragments.
    if ('kr' in word or 'кр' in word) and len(word) <= 4:
        return 1.3
    if 'chr' in word:
        return 0.5
    # Non-Latin creation/crime words and translations of other cr families.
    if word in {'创', '創'}:
        return 3.3
    if word == '刑':
        return 5.2
    if word.startswith(('创建', '创造', '創造', '创意', 'созд')):
        return 1.6
    # Crime, cry, crystal/crystallization, and criticism.
    if word in {'犯罪', '哭', '晶', '结晶', '批判'}:
        return 2.2
    # Innovation, crazy, crime, crisis, screen, and Japanese kr syllables.
    if word in {'创新', '狂', '罪', '죄', '危机', '屏幕', 'クロ', 'クラ'}:
        return 1.0
    if word.startswith(('drop', 'suicid', 'dramat')):
        return 0.85
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    value = response(token)
    if carry is not None and carry[0] == doc:
        if carry[1] and token.lower().startswith('r'):
            value += 0.4
    return (doc, token.lower().endswith('c')), value

