"""Detect local quantity restrictions, especially 'at least one'.

The negative response peaks on 'one' following 'least', and also marks
'least' itself. Smaller responses cover bounded numbers and near-universal
quantifiers. Only the preceding token is needed; document boundaries reset it.
Smaller positive/negative rules distinguish action-preposition phrases from
information, dependency, and obligation phrases. Constants are rounded
training averages. This is a partial reconstruction: other text returns zero
(except the small positive baseline for 'on').
"""
READS = ()

NUMBER_WORDS = set(
    'three four five six seven eight nine ten eleven twelve'.split()
)
UNIVERSALS = set('all any every everyone everything everywhere anything'.split())
COMPLETENESS = set(
    'always never entirely completely totally certainly nothing'.split()
)
BOUNDS = set('only exactly any no not almost nearly most just than'.split())


MOTION = set('go went run ran move pass plan'.split())
ACTIVITY = set('play work live operate fight'.split())
EVIDENCE = set('evidence information detail note hint instruction'.split())
OBLIGATION = set(
    'responsible responsibility liable liability necessary required '
    'essential important'.split()
)
ACTION_ROOTS = MOTION | ACTIVITY


def verb_root(word):
    # Ordinary English inflections, including a doubled final consonant.
    if word == 'goes':
        return 'go'
    if word.endswith('ing'):
        root = word[:-3]
    elif word.endswith('ed'):
        root = word[:-2]
    elif word.endswith('s'):
        root = word[:-1]
    else:
        return word
    if len(root) > 2 and root[-1] == root[-2]:
        root = root[:-1]
    if root + 'e' in ACTION_ROOTS:
        root += 'e'
    return root


def response(word, previous, first=False):
    if word == '至少':  # Chinese 'at least'.
        return -0.67
    if word == 'meno' and previous in {'al', 'nem'}:
        # Italian almeno ('at least') / nemmeno ('not even').
        return -0.75 if previous == 'al' else -0.45
    if word == 'least':
        if first:
            return -2.3
        if previous in {'at', 'very'}:
            return -1.4
        return -0.92 if previous == 'not' else -0.3
    if previous == 'least':
        if word == 'one':
            return -4.44
        if word == 'once':
            return -3.55
        if word in {'two', 'some', 'not', 'in', 'of', 'as'}:
            return -2.5
        if word in NUMBER_WORDS or word in {'squares', 'square', 'significant'}:
            return -1.3
        if word in {'a', 'an', 'the', 'about', 'that'}:
            return -1.15
        if not word:
            return -0.7
        return -0.6 if word.isalpha() else -0.3
    if previous in BOUNDS:
        if word in {'one', 'once', 'two'}:
            strength = 1.0 if previous == 'no' else 0.8
            if previous in {'just', 'than'}:
                strength = 0.55 if previous == 'just' else 0.3
            return -strength * (0.8 if word in {'once', 'two'} else 1.0)
        if word in NUMBER_WORDS:
            return -0.3
    if previous in {'almost', 'nearly', 'virtually', 'hardly'}:
        if word in UNIVERSALS:
            return -1.65 if previous == 'almost' else -1.2
        if word in COMPLETENESS:
            return -0.7
    if previous in {'not', 'no'}:
        if word in UNIVERSALS or word == 'matter':
            return -0.6
    root = verb_root(previous)
    if word in {'on', 'for'}:
        if root in MOTION:
            return 0.9 if word == 'on' else 0.5
        if root in ACTIVITY:
            if previous == 'work':
                return 0.23 if word == 'on' else 0.15
            return 0.57 if word == 'on' else 0.35
        if previous.rstrip('s') in EVIDENCE:
            return -0.4
        if previous in {'only', 'not', 'just'}:
            return -0.25
    if word == 'on':
        if previous.startswith('focus') or previous.startswith('concentrat'):
            return 0.55 if previous.endswith('ed') else 0.3
        if previous.startswith('depend'):
            return -0.2
        if previous in {'effect', 'effects', 'impact', 'constraint', 'constraints'}:
            return -0.25
        return 0.05
    if word == 'for':
        if previous in OBLIGATION or root == 'wait':
            return -0.46
        if previous in {'used', 'designed', 'made', 'called', 'intended'}:
            return 0.33
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    first = carry is None or carry[0] != document
    previous = '' if first else carry[1]
    spelling = prefix.token_strings[-1].strip()
    word = spelling.lower()
    value = response(word, previous, first)
    if spelling == 'Least':  # Title/name usage, rather than the lowercase bound.
        value = -0.28
    return (document, word), value

