"""Approximate the component's negative response to quoted/written material.

Recognize text, quotations, passages, scripture and their source constructions.
References such as 'the text' and 'following text' strengthen the response;
programming identifiers have a weaker text response. A short memory recognizes
'reading from' and 'quotes are from', resetting at document boundaries. Some
Chinese text/source compounds are recognized too. This captures the prominent
high-CI pattern, not the many small, unrelated lexical activations.
"""
READS = ()

QUOTES = {'quote', 'quotes', 'quotation', 'quotations', 'excerpt', 'excerpts'}
SCRIPTURE = {'bible', 'scripture', 'scriptures', 'verse', 'verses'}
SOURCE_ACTIONS = {
    'read', 'reads', 'learn', 'learned', 'learnt', 'learning',
    'extract', 'extracts', 'extracted', 'select', 'selected', 'taken',
    'choose', 'chosen', 'picked', 'downloaded', 'downloading', 'derived',
    'borrowed', 'line', 'lines', 'words', 'tunes', 'songs', 'clips',
}
BRIDGES = {'is', 'are', 'was', 'were', 'also', 'directly', 'actually'}
TRANSLATED_TEXT = {'texte', 'texto', 'текст', 'текста', 'тексты', 'тексте'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    recent = carry[1] if carry is not None and carry[0] == doc else ()
    previous = recent[-1] if recent else ''
    token = prefix.token_strings[-1]
    raw = token.strip().lstrip('._')
    word = raw.lower()
    spaced = token.startswith(' ')
    code = token.startswith(('.', '_'))
    value = 0.001

    if word in {'quote', 'quotes'}:
        value = -0.80 if not code else -0.53
        if raw.isupper():
            value = -0.23
    elif word in {'quotation', 'quotations'}:
        value = -0.65
    elif word in {'quoted', 'quoting'}:
        value = -0.37
    elif word in SCRIPTURE and spaced:
        value = -0.60
    elif word == 'verse':
        value = -0.20
    elif word == 'biblical':
        value = -0.45
    elif word in {'passage', 'passages'}:
        value = -0.64 if raw.islower() else -0.30
    elif word in {'excerpt', 'excerpts'}:
        value = -0.49
    elif word == 'cerpt':                 # The end of the word 'excerpt'.
        value = -0.92
    elif word in {'text', 'texts', 'textual'}:
        value = -0.38 if spaced else (-0.18 if code else -0.05)
        if word == 'texts' and spaced:
            value = -0.62
        if spaced:
            if previous in {'the', 'some', 'this', 'that'}:
                value = -0.60
            elif previous in {'following', 'ancient', 'annotated', 'greek'}:
                value = -0.80
            elif previous in {'full', 'original', 'more'}:
                value = -0.95
            elif previous in {'shared', 'phone'}:
                value = 0.05
    elif word in TRANSLATED_TEXT:
        value = -0.39
    elif word in {'paragraph', 'paragraphs', 'phrase', 'phrases',
                  'sentence', 'sentences'}:
        value = -0.20
    elif word == 'poem':
        value = -0.35
    elif word == 'lyrics':
        value = -0.50
    elif word == 'famous':
        value = -0.38
    elif word == 'plan' and previous == 'lesson':
        value = -0.55
    elif token == ' from':
        cue = recent[-2] if previous in BRIDGES and len(recent) > 1 else previous
        value = -0.01
        if cue in QUOTES or cue == 'translated':
            value = -1.0
        elif cue in {'reading', 'copied', 'adapted', 'lesson', 'lessons'}:
            value = -0.67
        elif cue in SOURCE_ACTIONS:
            value = -0.42
    elif token == ' of' and previous in {'text', 'texts'}:
        value = -0.50
    elif token in {'台词', '台詞', '歌词', '歌詞'}:
        value = -0.75
    elif token in {'这段', '這段', '那段', '一句', '句话', '句'}:
        value = -0.32
    elif token in {'文本', '文字', '原文'}:
        value = -0.27
    elif token == '文' and previous in {'经', '經', '注'}:
        value = -1.30 if previous != '注' else -0.94
    elif token in {'书', '書'} and previous in {'经', '經'}:
        value = -0.80
    elif token == '集' and previous == '全':
        value = -0.50
    elif token == '自' and previous in {'摘', '引'}:
        value = -0.50

    if not recent:                       # No preceding context at a new document.
        if word in {'quote', 'quotes'}:
            value = -1.50
        elif word in {'text', 'texts'}:
            value = -0.85
        elif word in {'sentence', 'sentences', 'poem'}:
            value = -0.62

    return (doc, (recent + (word,))[-2:]), float(value)

