"""Approximate the small formatting-related part of this component.

Chat delimiters have distinct offsets. The first chat header in a document
is especially negative, unlike subsequent message starts. Ordinary text is
kept near zero; these rules do not explain its word-specific variation.
"""

READS = ()

CHAT_MARKERS = {
    '<|im_start|>': 0.013,
    '<|im_end|>': 0.035,
    '<think>': 0.026,
    '</think>': -0.123,
    '<tool_call>': -0.042,
    '</tool_call>': 0.008,
    '<tool_response>': -0.021,
    '</tool_response>': -0.079,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, initial_chat = 0, text == '<|im_start|>'
    else:
        position, initial_chat = carry[1] + 1, carry[2]

    if initial_chat and position < 3:
        value = (-0.274, -0.124, 0.042)[position]
    elif text in CHAT_MARKERS:
        value = CHAT_MARKERS[text]
    elif text == 'assistant':
        value = -0.009
    elif text == 'user':
        value = 0.046
    elif text.strip().isdigit() and text.isascii():
        value = 0.0025
    elif not text.strip():
        value = 0.0006
    elif '\n' in text and text.strip() in {'.', '!', '?'}:
        value = -0.007
    else:
        value = -0.0025
    return (doc, position, initial_chat), value

programs.haiku:
"""Layer-0 MLP down_proj component 5783: a weak, mostly token-specific readout.

Its activation is small (std 0.03) and it almost never matters (CI never passes 0.1),
so no readable rule captures much of it. This program predicts a small per-kind offset
from the current token's surface form, plus the first-token-of-document effect:

- the first token of each document (positions reset there) is on average more negative;
- special markup tags (<|im_start|>, </think>, ...) are negative;
- plain numbers are slightly positive;
- otherwise a constant near the component's mean, -0.0015.

Token identity explains much more (a 48k-entry table reaches ~0.38 out of sample), but
that is a lookup table with no concept behind it; the readable rules here explain almost none.
"""

import re

READS = ()

MEAN = -0.0015
FIRST_TOKEN = -0.010
TAG = -0.0085
NUMBER = 0.0025


def _kind(text):
    if text.startswith("<") and text.rstrip().endswith(">"):
        return TAG
    if re.fullmatch(r"\s*\d+", text):
        return NUMBER
    return MEAN


def step(carry, prefix, upstream):
    # carry: (document id of the previous token, position within the current document)
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        pos = 0
    else:
        pos = carry[1] + 1
    if pos == 0:
        value = FIRST_TOKEN
    else:
        value = _kind(prefix.token_strings[-1])
    return (doc, pos), float(value)

