"""A detector for K-like letters, strongest as bare tokens at document starts.

Short K-initial pieces and capitalized pieces respond more weakly.
Forms of know and keep are exceptions. A word-piece immediately
following a bare K inherits a small response, stronger before a vowel.
A token ending in k reinforces a following k-initial token.
Document boundaries reset state.
Arabic kaf, Cyrillic ka and Greek kappa have analogous, weaker responses.
"""
READS = ()
K_LETTERS = 'kкکكκ'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != doc
    # State: document label, preceding bare letter, preceding raw token.
    previous = '' if fresh else carry[1]
    token = prefix.token_strings[-1]
    letters = ''.join(c for c in token if c.isalpha())
    lower = letters.lower()
    boundary = bool(token) and not token[0].isalpha()
    spaced = bool(token) and token[0].isspace()
    value = 0.0

    if lower in K_LETTERS and len(lower) == 1:
        if lower == 'k':
            value = 2.10 if letters.isupper() else 1.68
            if not spaced:
                value -= 0.30
            if fresh:
                value = 5.67 if letters.isupper() else 3.80
                if boundary:
                    value *= 0.75
        elif lower == 'к':
            value = 1.68 if letters.isupper() else 1.38
            if not boundary:
                value -= 0.38 if letters.isupper() else 0.75
            if fresh:
                value = 3.74 if letters.isupper() else 2.17
        elif lower in 'کك':
            value = 1.35 if boundary else 0.88
        else:
            value = 0.78 if boundary else 0.25
    elif lower.startswith('k'):
        n = len(lower)
        if (lower in ('know', 'known', 'knows', 'knowing', 'knew')
              or lower.startswith(('keep', 'kept'))):
            value = -0.04
        elif letters.isupper():
            value = 0.68
        elif letters[0].isupper():
            value = 1.10 if n == 2 else 0.85 if n == 3 else 0.65
        elif n <= 3:
            value = 0.72 if boundary else 0.40
        else:
            value = 0.38 if boundary else 0.22
        if fresh and value > 0 and not spaced:
            value *= 1.8 if letters[0].isupper() else 2.5
        if n == 2 and lower[-1] == 's':
            value = 0.02
    elif lower.startswith('к'):
        value = (0.65 if len(lower) == 2 else 0.30) if boundary else 0.12
    elif 'K' in letters:
        value = 0.60
    elif 'k' in lower and len(lower) <= 3:
        value = 0.25 if boundary else 0.17

    # A K split off from the rest of a word carries into its next piece.
    if token[:1].isalpha() and previous.lower() in K_LETTERS and previous:
        if previous in ('K', 'К'):
            value += (0.82 if token[0].lower() in 'aeiou' else 0.38) \
                if previous == 'K' else 0.30
        else:
            value += (0.46 if token[0].lower() in 'aeiou' else 0.18) \
                if previous == 'k' else 0.15
    if (not fresh and carry[2].lower().endswith('k')
            and token[:1].lower() == 'k'):
        value += 1.5 if len(letters) <= 3 else 0.3
    return (doc, letters if len(letters) == 1 else '', token), float(value)

