programs.luna:
"""Approximate contrast and negative-polarity words with short text cues."""

import re

READS = ()

CONTRAST = {"but", "nor", "except"}
STRONG_CUES = {"any", "much", "too", "doubt"}
DEGREE = {"any", "much", "too", "longer", "mais"}
POLARITY_WORDS = {
    "any", "much", "too", "longer", "ever", "more", "less",
    "know", "doubt", "sure", "real", "exist", "found", "always",
    "need", "miss", "change", "difference", "large", "comprehend",
    "null", "that",
}
NEGATION = re.compile(
    r"\b(?:no|not|never|without|neither|cannot|can't|can’t|"
    r"won't|won’t|don't|don’t|doesn't|doesn’t|didn't|didn’t|"
    r"isn't|isn’t|aren't|aren’t|wasn't|wasn’t|weren't|weren’t|n't|n’t)\b"
)


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().strip(".,!?;:()[]{}\"'*").casefold()
    doc = prefix.document_ids[-1]
    recent = []
    for i in range(max(0, len(prefix.token_strings) - 10), len(prefix.token_strings) - 1):
        if prefix.document_ids[i] == doc:
            recent.append(prefix.token_strings[i])
    context = "".join(recent).casefold()

    if word in CONTRAST:
        if word == "but" and re.search(r"\bnot\s+only\b", context):
            return None, 3.0
        return None, 1.15
    if word == "-" and re.search(r"\bnon\s*$", context):
        return None, 0.65
    if word not in POLARITY_WORDS:
        return None, 0.0
    if NEGATION.search(context):
        if word in {"found", "always"}:
            return None, -1.3
        return None, 2.9 if word in STRONG_CUES else 0.95
    if word in DEGREE:
        return None, 0.35
    return None, 0.0

programs.sol:
"""Approximate a pulse for a fresh, not-yet-filled opening delimiter.

Square brackets after spaces have the strongest negative pulse; parentheses
and braces also respond. Complete pairs and ordinary words predict zero.
Quotes, newlines, escapes and math scripts change the pulse. Nearby control
words, legal clause labels and TeX commands also adjust it. Context is limited to
the previous token and an 80-character tail, reset at document boundaries.
"""
import re

READS = ()
CONTROL_WORDS = {"if", "for", "while", "switch", "catch", "elif", "and", "or"}
LEGAL_PARTS = {"section", "subsection", "paragraph", "subparagraph", "clause"}


def opening(text):
    s = text.strip()
    if not s or any(c.isalnum() for c in s):
        return 0.0
    space = text.startswith(' ')
    if s in ('（', '【'):
        return -0.52
    # A quote after an opener has already started its contents.
    if s.endswith(('"', "'")):
        if s.startswith('{'):
            return -0.32 if space else -0.06
        if s.startswith('('):
            return -0.08
        if s.startswith('['):
            return -0.22 if space else 0.20
        return 0.0
    trailing_escape = s.endswith('\\')
    s = s.rstrip('\\')
    if not s or s[-1] not in '([{':
        return 0.0
    kind, before = s[-1], s[:-1]
    if before.endswith('\\'):
        return 0.0
    if kind in '([' and ']' in before:
        return 0.0
    if kind == '{' and '}' in before:
        return 0.3 if '_' in before else -0.3
    newline = '\n' in text
    if kind == '(':
        if newline:
            return -0.10
        if trailing_escape:
            return -0.55 if space else -0.27
        if ')' in before or '}' in before:
            return -0.35
        if '(' in before or '^' in before:
            return -0.62
        return -1.0 if space or before else -0.63
    if kind == '[':
        if newline:
            return -0.33
        if trailing_escape:
            return -1.05 if space else -0.46
        if not before:
            return -2.4 if space else -1.08
        if before[-1] in '#!':
            return -0.85
        if before[-1] in '=.,:':
            return -1.7
        return -1.2
    if newline:
        return -0.3 if '(' in before and ')' not in before else -0.72
    if '^' in before or '_' in before:
        return -0.4
    if '{' in before:
        return -0.8
    if '$' in before or '(' in before:
        return -1.05
    return (-2.14 if trailing_escape else -1.9) if space else -1.5


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, tail = '', ''
    else:
        _, previous, tail = carry
    text = prefix.token_strings[-1]
    value = opening(text)
    word = previous.strip()
    if text in (' (', '('):
        if word in CONTROL_WORDS:
            value = -1.23 if text.startswith(' ') else -0.97
        elif word in LEGAL_PARTS:
            value = -1.5
        elif word.isdigit():
            value = -0.81 if text.startswith(' ') else -0.39
        elif tail.endswith('\\left'):
            value = -0.7 if text.startswith(' ') else -0.06
        elif word.endswith(('"', "'", '”')):
            value = -0.70 if text.startswith(' ') else -0.45
        elif text.startswith(' ') and word and not word[-1].isalnum():
            value = -0.88
    elif text == ' [':
        if word and word[-1].isalpha():
            value = -2.65
        elif word.isdigit():
            value = -2.37
        else:
            value = -2.13
    elif text == '[':
        if tail.endswith('\\') or tail.endswith('\\left'):
            value = -0.1
        elif previous.endswith('\n') or not word:
            value = -1.25
    elif text.strip().rstrip('\\') == '{' and '\n' not in text:
        # TeX scripts and environment labels use braces differently from content.
        if tail.rstrip().endswith('^'):
            value = -0.4
        elif tail.rstrip().endswith('_'):
            value = -0.8
        elif word == 'import':
            value = -1.1
        elif word == 'param' and text.startswith(' '):
            value = -2.8
        else:
            command = re.search(r'\\([A-Za-z]+)\s*$', tail)
            if command:
                name = command[1]
                if name in ('begin', 'end'):
                    value = -0.52
                elif name in ('text', 'hat'):
                    value = -1.33
                elif name == 'label':
                    value = -1.07
