programs.sol:
"""Approximate a negative J/j-onset detector, not a topic detector.

Strip leading spaces and ASCII punctuation, then use the initial letter,
case, and fragment length: short J fragments are strongest, long words weaker.
The first two tokens of a document have a reduced J response.
Recognized exceptions are just, French je, JSON, Django's jango fragment,
Java, the join word family, and J-initial month names/abbreviations.  A few
non-Latin letters and syllables receive similar negative responses.  Short
fragments containing an internal j respond weakly too.

An immediately following letter-starting token inherits a smaller response
from a short J fragment; whitespace/punctuation and document boundaries stop
this continuation effect.  Everything else is predicted near zero.  This
captures the broad letter pattern, not each word's individual strength.
"""
import string

READS = ()
SEPARATORS = string.whitespace + string.punctuation


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    reset = carry is None or carry[0] != doc
    previous = '' if reset else carry[1]
    position = 0 if reset else carry[2] + 1
    token = prefix.token_strings[-1]
    word = token.lstrip(SEPARATORS)
    lower = word.lower()
    n = len(word)
    value = 0.001
    if lower.startswith('j'):
        if lower == 'json':
            value = -0.05
        elif lower == 'just':
            value = -0.32 if word[0].isupper() else -0.14
        elif lower == 'je':
            value = -1.15
        elif lower == 'jango':
            value = -0.22
        elif n == 1:
            if token.startswith(('.', '/')) and word.islower():
                value = -2.75
            elif token.startswith((' ', '\t', '\n')):
                value = -1.8
            else:
                value = -1.5
        elif n == 2:
            value = -2.4 if word[0].isupper() else -2.0
        elif n == 3:
            value = -2.2 if word[0].isupper() else -1.65
        elif n == 4:
            value = -1.3
        else:
            value = -1.18 if word[0].isupper() else -0.95
        if lower == 'java':
            value = -1.6
        elif lower.startswith('join'):
            value = -max(0.65, 0.95 - 0.07 * (n - 4))
        elif word in ('Jan', 'January', 'Jun', 'June', 'Jul', 'July'):
            if word.startswith('Jan'):
                value = -1.4
            elif word.startswith('Jun'):
                value = -1.0
            else:
                value = -0.85
        elif n == 2 and not word[1].isascii():
            value = -0.8
    # Related letters/syllables in other writing systems.
    elif word.startswith('ج'):  # Arabic jeem
        value = -1.65 if n == 1 and token != word else -0.95
    elif word.startswith(('ジャ', 'ジェ', 'ジョ')):  # Katakana ja/je/jo
        value = -1.6
    elif word.startswith(('じ', 'Дж', 'дж')):  # Hiragana ji; Cyrillic dzh
        value = -0.85
    elif word in ('я', 'Я'):  # Cyrillic ya
        value = -0.6 if word == 'Я' else -0.4 if token != word else -0.24
    elif word in ('จ', 'เจ', 'ਜ'):  # Thai forms; Gurmukhi jajja
        value = -1.0
    elif 'j' in lower and n <= 3:
        value = -0.7 if word.isupper() else -0.4

    if lower.startswith('j') and position < 2:
        value *= 0.68 if position == 0 else 0.9

    prev_word = previous.lstrip(SEPARATORS)
    if value == 0.001 and token and token[0].isalpha():
        if prev_word.lower().startswith('j') and len(prev_word) <= 3:
            if len(prev_word) == 1:
                value = -0.62 if previous != prev_word else -0.4
            else:
                value = -0.15
        elif prev_word.lower().endswith('j'):
            value = -0.2
    return (doc, token, position), value

programs.luna:
"""Mark tokens whose first written letter is j, including punctuation-prefixed forms."""

READS = ()
J_SOUND_CHARS = frozenset("جじジ")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    for char in token:
        if char.isalpha():
            if char.casefold() == "j" or char in J_SOUND_CHARS:
                return None, -1.6
            if char == "я":
                return None, -0.45
            break
        if char.isalnum():
            break
    return None, 0.0

programs.sol:
"""A local grammatical-negation detector.

The largest response is to 'not', scaled by its preceding auxiliary verb.
One intervening adverb or line break weakens that response. Contracted and
listed non-English negators are weaker. Minor rules cover 'let us', 'let's',
selected apostrophe-s constructions, and ordinary objects of 'do'. Most tokens
return zero. The last two tokens are carried across steps, never documents.
"""
READS = ()

# Activation after an auxiliary followed by lowercase 'not'.
AUXILIARY_NOT = {
    'do': 4.9, 'does': 4.7, 'did': 4.6,
    'is': 3.3, 'are': 3.3, 'was': 4.3, 'were': 3.8,
    'be': 2.7, 'am': 2.5,
    'has': 4.0, 'have': 3.9, 'had': 3.9,
    'will': 4.4, 'would': 4.2, 'shall': 4.7, 'should': 4.3,
    'can': 4.0, 'could': 3.9, 'may': 3.1, 'might': 3.2,
    'must': 4.1, 'need': 2.9,
}

# The stems immediately before the apostrophe-t of a negated auxiliary.
NEGATED_STEMS = {
    'don': 0.82, 'doesn': 1.18, 'didn': 1.18,
    'isn': 0.94, 'aren': 0.88, 'wasn': 1.3, 'weren': 1.0,
    'can': -0.1, 'couldn': 1.16,
    'won': 0.72, 'wouldn': 0.87, 'shouldn': 0.78,
    'haven': 0.7, 'hasn': 0.7, 'hadn': 0.68, 'ain': 0.35,
}

# Other negation and impossibility words; weaker than English 'not'.
OTHER_NEGATION = {
    'nor': 0.31,
    'unable': 0.7, 'impossible': 0.54, 'cant': 0.7, 'dont': 0.38,
    'nicht': 0.51, 'pas': 0.4, 'не': 0.28, 'không': 0.35,
    '不能': 0.74, '无法': 0.72, '不是': 0.49, '并不': 0.5,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    same_doc = carry is not None and carry[0] == doc
    previous = carry[1] if same_doc else ''
    earlier = carry[2] if same_doc else ''
    token = prefix.token_strings[-1]
    raw = token.strip()
    word = raw.lower()
    before = previous.strip().lower()
    two_back = earlier.strip().lower()
    value = 0.0
    not_word = raw.lstrip('_./-(').lower()
    if not_word == 'not':
        base = 1.8
        value = AUXILIARY_NOT.get(before, base)
        if before in {'i', 'you', 'he', 'she', 'we', 'they', 'it', 'that'}:
            value = 2.55
        # An intervening adverb or line break weakens the auxiliary's effect.
        modifier = before.endswith('ly') or before in {'also', 'still', 'now'}
        if two_back in AUXILIARY_NOT and (modifier or not before):
            value = base + 0.65 * (AUXILIARY_NOT[two_back] - base)
        if raw == 'NOT':
            value = 1.65 + 0.6 * (value - 1.8)
        elif raw == 'Not':
            value -= 0.2
        if before == 'if':
            value = 1.55
        elif previous.strip() == ',':
            value = 1.6
        if not previous:
            value = 2.5
    elif word == 'cannot':
        value = 1.95
    elif before + word == 'cannot':
        value = 1.4
    elif token in {"'t", '’t'}:
        value = NEGATED_STEMS.get(before, 0.15)
        if token == '’t' and before not in {'can', 'haven', 'hasn', 'hadn'}:
            value -= 0.07
        if previous.strip()[:1].isupper() and before in NEGATED_STEMS:
            value -= 0.35
    elif token in {"'s", '’s'}:
        if before == 'let':
            value = -1.15 if previous[:1].isspace() else -1.33
        elif before == 'here':
            value = -0.3
        elif before in {'men', 'women'}:
            value = -0.45
        elif before == 'people':
            value = -0.9
    elif word == 'us' and before == 'let':
        value = 1.3
    elif word == 'am' and before == 'i':
        value = 0.33
    elif token in {"'m", '’m'}:
        value = -0.27
    elif word in {'never', 'no'}:
        value = 0.05 if word == 'never' else -0.1
        if before in AUXILIARY_NOT:
            strength = AUXILIARY_NOT[before]
            value = 0.22 * (strength - 2.5)
            if before == 'can':
                value = 0.65
            elif before in {'should', 'could', 'would'} and word == 'never':
                value = 0.6
    elif before in {'do', 'does', 'did', 'doing'}:
        # Ordinary objects of 'do', in contrast to explicit 'not'.
        scale = 0.6 if before == 'does' else 1.0
        if word in {'it', 'that', 'a', 'an'}:
            value = -0.9 * scale
        elif word in {'this', 'the', 'i', 'to'}:
            value = -0.5 * scale
    elif raw == word:
        value = OTHER_NEGATION.get(word, 0.0)
    return (doc, token, previous), value

programs.haiku:
"""Negation detector for layers.0.mlp.down_proj component 5790.

This component fires on negation words, and most strongly on the word "not".
Its size depends on the word just before "not":
  - after do / does / did (verbal negation: "do not", "does not"): about 4.8
  - after can / will / would / should / could / must / was / were / has / had / have: about 4.2
  - after is / are / am / may / might / need: about 3.1
  - after punctuation or a conjunction ("," "and" "but" "or" "if" "to", or "'s", "'m"),
    as in "not only" / "but not": about 1.7
  - after any other word: about 2.0
Other negators are weaker: "cannot" about 2.0, "n't" (don't, doesn't, isn't) about 1.0,
"can't" about 0, "unable" and "impossible" about 0.6. "let's" is slightly negative (-1.1).
Every other token predicts 0. Only the current token and the one before it are read; the
previous word is ignored across a document boundary.
"""

READS = ()

DO = {"do", "does", "did"}
AUX = {"can", "will", "would", "should", "could", "must", "shall", "was", "were", "has", "had", "have"}
BE = {"is", "are", "am", "may", "might", "need"}
CONJ = {",", ".", "?", "!", ":", ";", "and", "but", "or", "if", "'s", "'m", "'re", "’s", "’m", "’re", "to"}


def activation(tok, prev):
    word = tok.strip().lower()
    if word == "not":
        if prev in DO:
            return 4.8
        if prev in AUX:
            return 4.2
        if prev in BE:
            return 3.1
        if prev in CONJ:
            return 1.7
        return 2.0
    if word == "cannot":
        return 2.0
    if word in ("'t", "’t"):
        return 0.0 if prev == "can" else 1.0
    if word in ("unable", "impossible"):
        return 0.6
    if word == "'s" and prev == "let":
        return -1.1
    return 0.0


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = ""
    if len(prefix.token_strings) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2].strip().lower()
    return carry, float(activation(tok, prev))

