"""Mark common written forms of negation, plus the opener “Let's”."""

READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()

    if word == "not":
        return None, 3.13
    if word in {"cannot", "can't", "can’t"}:
        return None, 1.98
    if word in {"n't", "’t", "'t"}:
        return None, 0.99

    same_document = (
        len(prefix.token_strings) > 1
        and prefix.document_ids[-1] == prefix.document_ids[-2]
    )
    if same_document and word in {"'s", "’s"}:
        previous = prefix.token_strings[-2].strip().casefold()
        if previous == "let":
            return None, -1.06

    return None, 0.0

programs.sol:
"""Lexical accompaniment and encounter cues, chiefly 'with'.

The immediately preceding token distinguishes abstract linking ('associated
with') from shared activities ('worked with'). Meeting, seeing, conversation
and a few translations provide related cues. Tool-call opening is a separate
cue. This is not a semantic parser: names and political parties also fire.
Unlisted tokens predict zero; predecessors never cross document boundaries.
"""
READS = ()

MEETINGS = set('meet meeting meetings party'.split())
CONVERSATIONS = set('met meets parties interview interviews interviewed '
                    'interviewing conversation conversations'.split())
SEEING = set('saw sees seeing visit dinner guests'.split())
SOCIAL_ACTIONS = set('see seen visited visiting encounter talking talked '
                     'introduce introduced invited interact'.split())
SOCIAL_EVENTS = set('gathering married friendship birthday'.split())

# These inflected roots express comparison, correlation or compatibility.
ABSTRACT_ROOTS = ('associat', 'correlat', 'consisten', 'compatib', 'compar',
                  'connect', 'align')
TECHNICAL_LINKS = set('connection contact accordance conjunction comparison '
                      'association replaced replace replacing combined combine '
                      'combining equipped comply compliance familiar help '
                      'treated treating diagnosed'.split())
SHARED_ACTIVITIES = set('meet meeting met work working worked works live living '
                        'lived lives love loved speak speaking spoke spoken '
                        'talk talking talked stay staying stayed travel '
                        'traveling travelled fight fighting fought'.split())
WITH_TRANSLATIONS = {'avec': 0.8, 'con': 0.6, 'mit': 0.4,
                     'com': 0.2, 'مع': 0.65}
# Chinese/Japanese seeing, meeting, interviews and gatherings.
MEETING_CHARACTERS = {'见到', '见面', '会见', '遇见'}
ENCOUNTER_CHARACTERS = {'見', '见', '遇', '訪', '宴', '宴会', '聚', '采访', '聊天'}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    spelling = token.strip()
    word = spelling.lower()
    previous = ''
    if len(prefix.token_ids) > 1:
        if prefix.document_ids[-2] == prefix.document_ids[-1]:
            previous = prefix.token_strings[-2].strip().lower()

    if word == 'with':
        value = 1.0 if spelling == 'With' else 0.70
        if token == ' with':
            if previous in TECHNICAL_LINKS:
                value = 0.28
            elif previous.startswith(ABSTRACT_ROOTS):
                value = 0.0
            elif previous in SHARED_ACTIVITIES:
                value = 1.35
            elif previous == ',':
                value = 0.93
    elif word in ('_with', '-with', '.with', '(with'):
        value = 0.75
    elif token == '<tool_call>':
        value = 0.945
    elif word in MEETINGS:
        value = 1.3
        if word == 'meeting' and not token.startswith(' '):
            value = 0.5 if spelling == 'meeting' else 1.1
    elif word in CONVERSATIONS:
        value = 0.9
        if word == 'met' and token != ' met':
            value = 0.4 if spelling == 'Met' else 0.19
    elif word in SEEING:
        value = 0.6
    elif word in SOCIAL_EVENTS:
        value = 0.5
    elif word in SOCIAL_ACTIONS:
        value = 0.35
        if word == 'see' and token != ' see':
            value = 0.14
    elif word in ('talk', 'together', 'encountered'):
        value = 0.2
    elif word in WITH_TRANSLATIONS:
        value = WITH_TRANSLATIONS[word]
        if not token.startswith(' ') or spelling[0].isupper():
            value *= 0.5
    elif word in MEETING_CHARACTERS:
        value = 1.5
    elif word in ENCOUNTER_CHARACTERS:
        value = 0.85
    elif word == '遇到':
        value = 0.6
    else:
        value = 0.0
    return None, value

programs.luna:
"""Recognize linear-algebra terms, array-code operations, and nearby math talk.
The clearest negative responses are to matrix and dimension vocabulary.
"""

READS = ()

STRONG_LINEAR_ALGEBRA = {
    "matrix", "matrices", "determinant", "dimension", "dimensions",
    "dimensional", "vector", "vectors", "tensor", "tensors",
    "eigen", "eigenvalue", "eigenvalues", "stencil",
}

STRUCTURE_AND_MATH = {
    "element", "elements", "array", "arrays", "row", "rows",
    "column", "columns", "axis", "axes", "shape", "real", "imaginary",
    "complex", "triangular", "entry", "entries", "rhs", "solver",
    "vectorial", "vec", "zero", "root",
    "roots", "coefficient", "coefficients", "constant", "component",
    "components", "derivative", "derivatives", "integral", "integrals",
    "polynomial", "diagonal", "sign", "product", "degree", "norm",
    "gradient", "scalar", "dot", "fractional",
}

NUMERICAL_CODE = {
    "numpy", "np", "matlab", "linalg", "reshape", "zeros", "stride",
    "sizeof",
}


def step(carry, prefix, upstream):
    """Classify the current word, retaining a short mathematical context."""
    doc = prefix.document_ids[-1]
    previous_doc, word, previous_word, recent_math = (
        carry if carry is not None else (doc, "", "", 0)
    )
    if doc != previous_doc:
        word, previous_word, recent_math = "", "", 0

    prior_math = max(0, recent_math - 1)
    last_completed = previous_word
    for char in prefix.token_strings[-1].lower():
        if "a" <= char <= "z":
            word = (word + char)[-32:]
        else:
            if word:
                last_completed = word
            word = ""

    surface = prefix.token_strings[-1].lower()
    if surface.startswith(".") and word in {"array", "zeros"}:
        value = -1.3
    elif word in NUMERICAL_CODE:
        value = -0.8
    elif word == "point" and last_completed == "floating":
        value = -0.8
    elif word in STRONG_LINEAR_ALGEBRA:
        value = -0.8
    elif word in STRUCTURE_AND_MATH:
        value = -0.65 if prior_math else -0.38
    elif word == "fraction":
        value = 0.2
    else:
        value = 0.0

    math_marks = "$^∑∫≤≥×÷±√"
    if word in STRONG_LINEAR_ALGEBRA or word in STRUCTURE_AND_MATH:
        recent_math = 6
    elif any(mark in surface for mark in math_marks):
        recent_math = 6
    else:
        recent_math = prior_math
    return (doc, word, last_completed, recent_math), value

