"""A mostly lexical detector for roll/oll, rather than rolling situations.

Large negative values mark roll, poll, toll, enroll and their spelling relatives.
Short oll fragments respond even inside unrelated words. Chinese rolling words
also respond. Importance/significance have a smaller positive signal. Reduced
responses extend onto split-word endings and a following 'of'. Other tokens
are zero; weaker unrelated lexical effects and detailed context are omitted.
Memory resets at document boundaries.
"""
READS = ()


def lexical(token):
    word = token.strip().lstrip('._-')
    s = word.lower()
    space = token[:1].isspace()
    if s in {'roll', 'oll'}:
        value = -5.4
        if s == 'roll' and (not space or not word.islower()):
            value = -6.1
    elif s in {'poll', 'toll', 'holl'}:
        value = -4.6
    elif s in {'rolls', 'olls', 'polls', 'tolls'}:
        value = -5.0
    elif s in {'rolling', 'rolled', 'polling'}:
        value = -4.3
    elif s == 'enroll':
        value = -5.1
    elif s in {'enrol', 'enrolled'}:
        value = -3.2
    elif s in {'enrollment', 'enrolment'}:
        value = -3.9
    elif s in {'roller', 'rollers', 'oller'}:
        value = -2.1 if space else -3.8
    elif s in {'scroll', 'scrolls', 'scrolling', 'doll', 'olla', 'ollen'}:
        value = -2.3
    elif s in {'troll', 'trolls', 'trolley', 'rolley', 'rollment', 'payroll'}:
        value = -2.7
    elif s == 'rol':
        value = -1.1 if word.istitle() else -2.2
    elif s in {'coll', 'moll', 'foll', 'olle'}:
        value = -1.7
    elif s in {'dollar', 'dollars', 'ollar', 'collar', 'dolls', 'olly'}:
        value = -1.0
    elif s in {'滚', '滾', '滚动', '滾動', '滚滚', '滾滾'}:
        value = -3.7
    elif s in {'importance', 'significance'}:
        value = 0.85
    elif s == 'progress':
        value = -0.9
    else:
        value = 0.0
    if token.startswith(('.', '_')):
        value *= 0.85
    elif token.startswith('-'):
        value *= 1.3
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous, strength = carry[1:] if carry and carry[0] == doc else ('', 0.0)
    value = lexical(token)
    # Recognize split en+roll, un+roll and cont+rolling spellings.
    if token.lower() in {'roll', 'rolling'}:
        before = previous.strip().lower()
        rolling = token.lower() == 'rolling'
        if before.endswith('cont'):
            value = -0.7 if rolling else -4.4
        elif before in {'en', 'un'}:
            value = -5.7 if rolling else -7.6
    direct = value
    if value == 0.0:
        if token.lower() == ' of':
            value = 0.55 * strength
        elif strength < -1.0:
            if token.lower() in {'s', 'ed', 'ing', 'ings'}:
                value = 0.55 * strength
            elif token.lower() in {'ment', 'ments'}:
                value = 0.65 * strength
            elif token.lower() in {'er', 'ers', 'ation', 'ations', 'ster'}:
                value = 0.3 * strength
    return (doc, token, direct), float(value)

