        grammar = word.lower() in GRAMMAR_WORDS
        bare = not token.startswith(' ')
        value = 1.05 + 0.36 * math.log1p(len(word)) - 0.18 * bare
        value -= 0.29 * grammar + 0.28 * (grammar and bare and word[0].isupper())
        return value + 0.17 * (word.isupper() and len(word) > 1)
    if word.isalpha():
        return 1.38 + 0.34 * any('\u4e00' <= c <= '\u9fff' for c in word)
    return 1.38 if any(c.isalpha() for c in word) else 0.58


