    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    token_id = prefix.token_ids[-1]
    position, recent = ((0, ()) if carry is None or carry[0] != doc
                        else (carry[1] + 1, carry[2]))
    word = token.strip()
    value = opener(token) if position == 0 else 0.26 / position - 0.008
    previous = recent[-1][1] if recent else ''
    if position:
