            value -= 0.025
            gain = 0.06
        elif not word:
            gain = 0.09
        elif any(c.isalpha() for c in word):
            gain = 0.81 if word.isascii() else 1.02
        else:
            gain = 0.41
        if distance:
            value += gain if distance == 1 else 0.2 * gain * 8 / distance**3
