        value = ROLES[token][0 if position == 1 else 1]
    elif token in {'<think>', '</think>'}:
        value -= 0.28
    elif token == '</tool_call>':
        value += 0.20
    elif token.startswith('\\"'):
        value += 0.19
    elif word == '\\':
        value -= 0.08
    return (doc, position, (recent + ((token_id, token),))[-8:]), float(value)

