END_OF_TOOL_TEXT = ("</tool_call>", "</tool_response>")


def first_token_value(text):
    """Activation of the first token of a document, judged by its characters."""
    if text.startswith("<|"):
        return -0.5  # special markers such as <|im_start|>
    core = text.strip()
    if core == "":
        return 0.2  # spaces or tabs alone
    if "\n" in text or "\r" in text:
        return 0.5
    if core.isalpha():
        return 1.4  # a word, including CJK characters
    if core.isdigit():
        return 0.4
    return 0.3  # punctuation and symbols


def early_value(position):
    """Small positive values for the first few tokens after a document start."""
    if position == 1:
        return 0.16
    if position < 4:
        return 0.10
    if position < 8:
        return 0.06
    if position < 32:
        return 0.02
    return 0.0


def step(carry, prefix, upstream):
    # carry: (position within the document of the previous token, its document id)
    if carry is None or prefix.document_ids[-1] != prefix.document_ids[-2]:
        position = 0
    else:
        position = carry[0] + 1
    text = prefix.token_strings[-1]
    if position == 0:
        value = first_token_value(text)
    elif text == "<|im_end|>":
        previous = prefix.token_strings[-2]
        value = 1.4 if previous in END_OF_TOOL_TEXT else -0.2
    else:
        value = early_value(position)
    return (position, prefix.document_ids[-1]), value

