programs.sol:
"""An unusual-whitespace response, rather than a general text feature.

Space-prefixed non-breaking spaces are strongest; NBSP runs, tab/space
patterns, and whitespace-filled blank lines respond less. The previous token
adjusts NBSP responses. Unicode ellipses, zero-width spaces, and left-to-right
marks also respond. Everything else is assigned zero.
Constants and width curves summarize training observations. Only the previous
token is remembered, with a reset at document boundaries.
"""
import re

READS = ()


def response(token, previous=""):
    if token.isspace():
        spaces = token.count(' ')
        tabs = token.count('\t')
        nbsp = token.count('\u00a0')
        if nbsp:
            after_whitespace = not previous or previous.isspace()
            if spaces:
                if nbsp == 1:
                    return 4.6 if after_whitespace else 6.25
                return 3.8 if after_whitespace else 4.9
            if nbsp > 1:
                return 1.25 if after_whitespace else 1.9
            if not previous or '\u00a0' in previous:
                return 0.17
            if previous.endswith(' '):
                return 0.75
            if previous.endswith(('\n', '\r')):
                return 0.55
            return 0.26 if previous[-1].isdigit() else 0.36
        if tabs and spaces and '\n' not in token and '\r' not in token:
            if token.startswith(' '):
                return (2.3 if tabs <= 2 else 1.5) if spaces < 4 else 1.2
            if tabs > 1:
                return 1.1
            if spaces <= 9 and spaces % 4 == 1:
                return 1.25
            return max(0.4, 1.02 - 0.022 * spaces)
        if re.search(r'[\r\n][ \t]+[\r\n]', token):
            return 0.55
        if tabs and not spaces:
            if tabs == 1:
                return -0.10 if token == '\t' else 0.03
            return 0.12 + 0.014 * max(0, tabs - 6) ** 2
        if tabs and spaces:
            return 0.5
    bare = token.lstrip(' ')
    if bare and set(bare) == {'…'}:
        return 0.16 * len(bare) + (0.72 if token.startswith(' ') else 0.0)
    if bare in {'\u200b', '\u200e'}:
        return 0.6 + (0.15 if token.startswith(' ') else 0.0)
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == document else ''
    token = prefix.token_strings[-1]
    return (document, token), float(response(token, previous))

