"""A sparse spelling detector, not general topic recognition.
'Course' is strongly positive, 'threat' and intimidation words negative. Calculation
words, carbon/salt chemistry, and Paul have smaller positive responses. Several Chinese
course, chemistry, fear, and power words are recognized too. Keyword fragments
can fire inside unrelated words. A few following prepositions echo the signal.
Small chat/tool delimiter responses depend on whether a document is starting.
These spellings account for conspicuous activation peaks. Unmatched tokens
default to zero; document boundaries reset state.
"""
READS = ()


def lexical_signal(token, previous):
    text = token.strip()
    word = text.lower().lstrip('_-')
    if word in {'course', 'courses'}:
        if token.startswith('_'):
            return 1.6
        return 2.05 if text == 'course' else 1.8
    if word.startswith('threat'):
        if token.startswith('-') and word == 'threatening':
            return -1.5
        if word == 'threat':
            return -3.6
        if word == 'threatening':
            return -2.8
        return -3.3 if word == 'threatened' else -3.1
    if word == 'reat':
        return -2.3 if previous.lower().endswith('th') else -1.1
    if word in {'ourse', 'ourses', 'cour'}:
        return 1.5 if word == 'cour' else 0.85
    if word.startswith('intimid') or word == 'formidable':
        return -1.7
    if word in {'ominous', 'looming', 'jeopard'}:
        return -1.1
    if word == 'imid':
        return -1.25
    if word == 'alc':
        return 0.52
    if word in {'arbon', 'arbonate', 'bon'}:
        return 1.45 if word == 'arbon' or previous.endswith('car') else 0.6
    if word in {'calc', 'calcul'}:
        return 0.85
    if word.startswith('calcul'):
        if word == 'calculated':
            return 0.28
        if word == 'calculator' and text[:1].isupper():
            return 0.25
        return 0.56
    if word == 'carbon':
        return 1.3
    if word in {'carbonate', 'carbohydrate', 'calcium', 'salt', 'salts', 'saline'}:
        return 0.9 if word == 'salt' else 0.65
    if word in {'sugar', 'glucose'}:
        return 0.5
    if word == 'paul':
        return 0.9
    if word in {'cache', 'cached', 'caches'}:
        return 0.5 if token.startswith(('_', '-')) else 0.25

    # Course and chemistry vocabulary in other scripts.
    if text in {'课程', '課程'}:
        return 1.5
    if text in {'课', '課', '当然'} or word == 'курс':
        return 0.6
    if text == 'コース':
        return 1.1
    if text == '碳':
        return 2.1
    if text in {'盐', '鹽', '钙', '鈣'}:
        return 1.0
    if text == '糖':
        return 0.5
    # Intimidation, power, and fear; posture/gestures are weaker.
    if text in {'威胁', '威脅'}:
        return -4.0
    if text in {'威', '势', '勢'}:
        return -0.95 if previous.endswith(('姿', '手')) else -2.4
    if text in {'形势', '态势', '之势', '势头'}:
        return -2.1
    if text in {'优势', '的优势', '权威', '气势'}:
        return -1.4
    if text in {'趋势', '的趋势', '发展趋势', '走势', '势力', '局势'}:
        return -0.75
    if text in {'恐', '怖', '惧', '懼', '逼'}:
