READS = ()

ROMAN_NUMERALS = set("II III IV VI VII VIII IX XI XII XIII XIV XV XVI XX".split())
COUNTRY_LABELS = {"US", "UK", "USA"}
TECH_LABELS = set("TV DVD USB API SQL XML CSS HTML HTTP HTTPS JSON".split())
BYTE_UNITS = {"KB", "MB", "GB", "TB"}
COMMON_WORDS = set("THE THIS THAT THESE THOSE AND ARE WAS WERE HAVE HAS "
                   "WITH FROM FOR NOT ALL OUR YOUR OTHER BUT".split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
