    previous_length = len(previous.strip())
    fragment = text.isalpha() and text.isupper()
    plural = text.isalpha() and text.endswith('s') and text[:-1].isupper()

    value = 0.0003
    if fragment or plural:
        length = capitals if plural else len(text)
        if length >= 4:
            value = -.03 + .54 * ordinary - .12 * upper
        elif capital_continuation:
