            word = ''
            pieces = 0
    pieces = pieces + 1 if word else 0
    size = max(1, len(text))
    normal_letters = sum(c.isalpha() and not c.isupper() for c in text)
    ordinary = .75 * ordinary + .25 * normal_letters / size
    upper = .75 * upper + .25 * capitals / size
