import re

READS = ()
QUOTES = '\"\'`“‘'
MATH = re.compile(r'\\[A-Za-z]{2,}|\$[^$\n`]{1,60}\$')
ARGUMENT = re.compile(r'\\[A-Za-z]{2,}$')


def opening(token, tail):
    s = token.strip()
    space = token.startswith(' ')
    newline = '\n' in token or '\r' in token
