        before = s.split('${', 1)[0]
        if '`' in before:
            return 7.35
        if '"' in before or "'" in before:
            return 7.5 if '=' in before else 6.55
        if not before and not space and tail.endswith('$'):
            return 2.65
        if '=' in before:
            return 6.7
        if before.startswith('}') or '.' in before:
            return 5.0
        return 6.0 if '`' in tail else 4.15 if MATH.search(tail) else 5.5
    if '#{' in s:
        return 5.2 if any(q in s for q in QUOTES) else 3.0
    if s.startswith(('$"{', '$@"{', '@$"{')):
        return 4.4
    if '%{' in s:
        return 2.1
    if '《' in s:
        return 1.0
    if s.startswith('$\\'):
        return 0.8 if space else 1.0
    if '$(' in s:
        return 2.2 if s.startswith('=') else 1.4
    if '{' in s:
        before, after = s.split('{', 1)
        if '^' in before or '_' in before or s == '}{':
            return 0.05
        if s.startswith('{{'):
            return 2.2 if '$' in s else 1.5 if space else 1.25
        if s.startswith(('"{', "'{", '`{', '="{')):
            return 2.0 if '{{' in s else 1.5 if space else 2.3
        if s.startswith(('({', '[{', '/{', '-{')):
            return 0.66 if newline else 1.2
        if s.startswith(('{"', "{'")):
            return 0.85 if space else 0.38
        if s.startswith('{\\'):
            return 0.02 if ARGUMENT.search(tail.rstrip()) else 0.47
        if s == '{':
            previous = tail.rstrip()
            if newline:
                if previous.endswith(('=', ':', 'return')):
                    return 0.5
                if previous.endswith((',', '[')):
                    return 0.35
                return -0.07 if previous.endswith(')') else 0.05
            return -0.2 if ARGUMENT.search(previous) else 0.56
        if after[:1].isalnum() or s.startswith(('{}', '{-')):
            return 0.0
        return 0.0 if newline else 0.7
    if s.count('(') >= 2 and ')' not in s:
        return min(1.7, 1.1 + 0.5 * (s.count('(') - 2))
    if s.startswith(('[(', '([', '[[')):
        return 0.85
    if len(s) > 1 and s[0] in QUOTES:
        if s[1] in '$[<@#':
            return 0.75
        if s[1] in '/\\^(-%':
