"""Layer 0 MLP down_proj, hidden unit 5813: a rough word-list approximation.

The component's output is a small, diffuse function of the current token; the
preceding tokens add little. Read as word classes:

- positive: religious and Christian vocabulary (Christ, Jesus, Bible, divine,
  worship, pastor, blessed, Hindu), and -ly adverbs such as "simply" and "easily";
- negative: object pronouns and two tool-template tags (them, him, who, NAME,
  <tool_response>), concrete everyday nouns (eye, floor, bed, skin, flesh), and
  place and person names (Australia, John, Iraq).

Each listed word predicts its class's mean activation on training text; every
other word predicts 0. On 1024 eval rows this explains about 0.9% of the
activation variance (Pearson r 0.10), and putting it into the model does about
what switching the component off does (kl_fraction 0.99). It is a sketch: a
per-token lookup explains far more (about 11% with the top 1000 tokens), but
it has no concept behind it.
"""

READS = ()

RELIGIOUS = {
    "christ", "christian", "christians", "christianity", "jesus", "bible",
    "gospel", "divine", "hindu", "hindus", "worship", "pastor", "blessed",
    "bless", "blessing", "scripture", "scriptures", "faith", "church", "prayer",
}
OBJECT_PRONOUNS = {"them", "him", "who", "whom", "others", "themselves"}
TEMPLATE_WORDS = {"NAME", "<tool_response>", "</tool_response>"}
CONCRETE_NOUNS = {
    "eye", "hair", "skin", "leg", "floor", "ground", "wall", "stream", "bed",
    "front", "middle", "flesh", "wood", "house", "pants", "mouth", "garments",
}
PLACES_PEOPLE = {
    "Australia", "America", "England", "France", "Iraq", "Yemen", "Oman",
    "John", "Abraham", "Egyptians", "Israel",
}
VALUES = {
    "religious": 0.07,
    "ly_adverb": 0.02,
    "pronoun": -0.06,
    "concrete": -0.07,
    "place_person": -0.08,
}


def _class_of(word):
    """The class of one token's text (stripped), or None. Matching ignores case,
    except for the template tags and the capitalised place and person names."""
    lower = word.lower()
    if lower in RELIGIOUS:
        return "religious"
    if lower in OBJECT_PRONOUNS or word in TEMPLATE_WORDS:
        return "pronoun"
    if lower in CONCRETE_NOUNS:
        return "concrete"
    if word in PLACES_PEOPLE:
        return "place_person"
    if word.isascii() and word.isalpha() and lower.endswith("ly") and len(word) > 4:
        return "ly_adverb"
    return None


