    word = prefix.token_strings[-1].strip()
    cls = _class_of(word)
    return carry, float(VALUES[cls]) if cls else 0.0

programs.sol:
"""Approximate the opening of parenthetical asides, especially ' ('.
The preceding token's grammatical/character class and the length of the
current phrase set the strength. Syntax and function words weaken it.
Separate rules cover recurring time intervals, Chinese distributive
expressions, and tool-opening markers. All other activations are zero.
Phrase length and the preceding token reset at document boundaries.
"""
import re

READS = ()
FUNCTION_WORDS = set('''
a an the this that these those my your his its our their some any each
every all both either neither no another other what which whose
and or but nor so yet if then than because although though while since unless
as when where whether not of to in on at by for with from into onto over under
between among through about after before during without within throughout
against upon per via is are was were am be been being have has had do does did
can could shall should will would may might must
'''.split())
CONTROLS = set('''
if for while switch catch foreach return assert sizeof typeof func function
'''.split())
PERIODIC = {
    'hourly': 0.80, 'daily': 0.80, 'weekly': 0.72, 'monthly': 0.65,
    'yearly': 0.85, 'annual': 0.68, 'annually': 0.58,
    'quarterly': 0.49, 'everyday': 0.37,
}
PAREN_BASE = {
    'space': -0.02, 'operator': -0.09, 'colon': -0.23,
    'punctuation': 0.06, 'quote': 0.51, 'number': 0.40,
    'control': 0.04, 'function': 0.12, 'unicode': 0.50,
    'letter': 0.35,
    'word': 0.63, 'fragment': 0.52, 'other': 0.25,
}


def previous_kind(token):
    s = token.strip()
    if not s:
        return 'space'
    if any(c in s for c in '=+-/<>|&→⇒'):
        return 'operator'
    if s in (':', '):'):
        return 'colon'
    if s in ('.', ',', ';', ')', ']', '}', '?', '!', '(', ').', '),'):
        return 'punctuation'
    if s in ('"', "'", '`', '”', '’', '»'):
        return 'quote'
    if s.isdigit() or s in ('%', '²', '³'):
        return 'number'
    if s.lower() in CONTROLS:
        return 'control'
    if token[0].isspace() and s.lower() in FUNCTION_WORDS:
        return 'function'
    if s.isalpha():
        if not s.isascii():
            return 'unicode'
        if len(s) == 1:
            return 'letter'
        return 'word' if token[0].isspace() else 'fragment'
    return 'other'


def paren_strength(previous, kind, phrase):
    value = PAREN_BASE[kind] + 0.34 * phrase
    if kind in ('word', 'fragment'):
        word = previous.strip()
        value += 0.11 * min(len(word), 12) / 12
        value += 0.06 * word.endswith('s') - 0.09 * word.isupper()
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, chars = ('', 0) if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip()
    kind = previous_kind(previous)
    phrase = min(chars, 120) / 120
    aside = paren_strength(previous, kind, phrase)
    value = 0.0

    if token in ('<tool_call>', '<tool_response>'):
        value = 2.03 if token == '<tool_call>' else 0.90
    elif word.lower() in PERIODIC:
        value = PERIODIC[word.lower()] - 0.23 * (word in ('Annual', 'Monthly'))
    elif word in ('每天', '每日', '每周', '每月', '每个月', '每年'):
        value = 2.15  # Chinese: every day, week, month, or year.
    elif word.startswith('每'):
        value = 1.15 if word in ('每次', '每一次', '每个人') else 0.80
    elif word.startswith('各'):
        value = 1.65 if word in (
            '各地', '各国', '各区', '各级', '各界', '各方', '各行各业'
        ) else 0.85  # Distributive places/groups versus generic 'each'.
    elif word in ('一天', '一周', '一年', '一生', '全年', '全天'):
        value = 0.75  # A day/week/year/lifetime, or a whole day/year.
    elif len(word) == 2 and word[0] == '全' and word[1] in '国國省市县縣区區':
        value = 1.0  # Throughout a country, province, city, county, or district.
    elif word in ('日々', 'täglich'):
        value = 0.90  # Japanese/German: daily.
    elif token == ' (':
        value = aside if previous else 0.05
    elif token.startswith(' (') and 2 < len(token) <= 4:
        if all(c in '\\"\'“`$#@*/[<._>&' for c in token[2:]):
            value = 0.65 * aside
    elif token == '（':
        value = 0.48 if kind == 'unicode' else 0.25
    elif token == '—':
        value = 0.09 + 0.78 * aside
    elif token == ' —':
        value = 0.95 * phrase
        if kind == 'function':
            value -= 0.17
        elif kind in ('word', 'fragment'):
            value += -0.05 + 0.12 * previous.endswith('s')
    elif token == ' –':
        value = 0.35 * phrase
        if kind == 'word':
            value += 0.26
        elif kind in ('function', 'unicode', 'fragment'):
            value += 0.10
        elif kind in ('punctuation', 'letter'):
            value -= 0.08

    pieces = re.split(r'[\n.!?;—–()]', token)
    chars = len(pieces[-1]) if len(pieces) > 1 else chars + len(token)
    return (doc, token, chars), float(value)

programs.luna:
"""Use a few visible text cues for this rarely active component.

Its clearest cue is opening a parenthetical aside.  Smaller recurring cues
include tool hand-off markers, dash punctuation, and frequency words.
"""

READS = ()


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    token = raw.lstrip()
    if token in ("<tool_call>", "<tool_response>"):
        return None, 1.8 if token == "<tool_call>" else 0.8
    if raw.startswith(" ("):
        return None, 0.52
    if token.startswith("（"):
        return None, 0.47
    if token.startswith(("–", "—")):
        return None, 0.12
    if token.lower().strip() in {
        "daily", "weekly", "monthly", "quarterly", "yearly",
        "annual", "annually", "hourly", "日々", "毎年",
    }:
        return None, 0.70
    return None, 0.0

"""Predict rare typography-sensitive bursts in East Asian text.

The main cues are interpuncts and opening delimiters after East Asian text;
line-ending ellipses and fullwidth list punctuation get smaller predictions.
"""

READS = ()

INTERPUNCTS = {"・", "·"}
OPENERS = {"（", "“", "「", "『", "【", "《", "〈", "〔", "［", "｛"}
WAVE_MARKS = {"~", "〜", "～"}


def east_asian(text):
    return any(
        0x2E80 <= ord(ch) <= 0x9FFF
        or 0x3040 <= ord(ch) <= 0x30FF
        or 0xAC00 <= ord(ch) <= 0xD7AF
        or 0xF900 <= ord(ch) <= 0xFAFF
        or 0xFF00 <= ord(ch) <= 0xFFEF
        for ch in text
    )


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    token = raw.strip()
    previous = ""
    if prefix.position and prefix.document_ids[-1] == prefix.document_ids[-2]:
        previous = prefix.token_strings[-2]
    asian_context = east_asian(previous)

    if token in INTERPUNCTS and asian_context:
        return None, 1.2
    if token in OPENERS and asian_context:
        return None, 0.4
    if token == "《":
        return None, 0.13
    if token in WAVE_MARKS and asian_context:
        return None, 0.5
    if token == "．":
        return None, 0.19
    if token == "！" and asian_context:
        return None, 0.12
    if "\n" in raw and token == "...":
        return None, 0.15
    return None, 0.0

programs.sol:
"""An approximate spelling detector for short 'ot' words and fragments.

The short-spelling table calibrates the response; added letters weaken it.
Common false matches are excluded. 'Not' is strongly suppressed immediately
following do/does/did, moderately suppressed by other auxiliaries. Cyrillic
'от' and end-of-text markers also fire. State is just the preceding token,
reset at document boundaries; this is not a general negation detector.
"""
READS = ()

# Strengths of the common short -ot spelling families, at a word boundary.
OT_ROOTS = {
    'ot': 3.9,
    'lot': 3.75,
    'dot': 4.2,
    'spot': 4.4,
    'pot': 3.6,
    'got': 2.05,
    'hot': 2.65,
    'plot': 2.5,
    'rot': 2.25,
    'bot': 3.25,
    'cot': 3.0,
    'tot': 1.95,
    'mot': 3.4,
    'slot': 1.95,
    'phot': 3.0,
    'quot': 2.7,
    'prot': 1.4,
}

DO = {'do', 'does', 'did'}
MODALS = {'can', 'could', 'will', 'would', 'shall', 'should',
          'may', 'might', 'must', 'need'}
BE = {'is', 'are', 'was', 'were', 'be', 'been', 'being'}
HAVE = {'has', 'have', 'had'}


def spelling_value(token):
    s = token.strip().strip('._/(-').lower()
    if token == '<|endoftext|>':
        return 1.31
    if 'от' in s:
        before, after = s.split('от', 1)
        if not before:
            base = 2.55 if token.startswith(' ') else 4.15
        else:
            base = 3.0 / (1 + max(0, len(before) - 1))
        return base / (1 + len(after))
    if s == 'ôt':
        return 2.85
    if s.startswith(('total', 'bottom', 'cannot', 'cdot', 'scott')):
        return 0.0
    if 'ot' not in s:
        return 0.0
    if s.startswith('not'):
        if s in {'note', 'notes'}:
            return 0.9
        if s == 'noted':
            return 0.55
        return 0.0
    if any(cluster in s and s != cluster for cluster in ('oth', 'oot')):
        return 0.0
    before, after = s.split('ot', 1)
    root = before + 'ot'
    base = OT_ROOTS.get(root, 3.3 / (1 + 0.6 * max(0, len(before) - 1)))
    if not token.startswith(' '):
        base += 0.7
    if after == 's':
        return base * 0.84
    return base / (1 + 0.65 * len(after))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    s = token.strip().strip('._/(-').lower()
    if s == 'ots' and previous in {'ld', 'cd'}:
        # Continuations of LaTeX ellipsis commands, not ordinary -ot words.
        value = 1.0 if previous == 'ld' else 1.8
    elif s == 'dots' and previous.endswith('\\'):
        value = 1.56
    elif s == 'not':
        if not token.startswith(' '):
            value = 2.05
        elif previous in DO:
            value = -0.08
        elif previous in MODALS:
            value = 0.30
        elif previous in BE:
            value = 0.91
        elif previous in HAVE:
            value = 0.71
        else:
            value = 1.55
        if token.strip() == 'Not':
            value = 1.75
    else:
        value = spelling_value(token)
    return (doc, s), float(value)

programs.haiku:
"""Layer-0 MLP down-projection component 5816, read as a spelling detector.

It fires on word-pieces spelled with the letters "ot": the rhyme family of
"-ot" (pot, lot, dot, spot, plot, hot, got, shot, OT, ot, ots), the Russian
preposition "от" ("from") and similar Cyrillic "-от" pieces, strongest when the
piece has no leading space. It fires more weakly on "not" (silent after
"do/does/did", weak after a modal such as "could" or "will"), on the
end-of-text token, and on other pieces that merely contain "ot" (motor, vote,
quote). Everything else stays near zero.
"""

import re
from collections.abc import Mapping

READS = ()

CONSONANTS = "bcdfghjklmnpqrstvwxzбвгджзклмнпрстфхцчшщ"
RIME = re.compile(rf"[{CONSONANTS}]{{0,2}}(ot|от)s?")
DO_FORMS = {"do", "does", "did"}
MODALS = {"could", "would", "should", "will", "can", "may", "might", "must", "shall", "need"}


def step(carry, prefix, upstream: Mapping):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    spaced = token[:1].isspace()
    previous = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
    if token == "<|endoftext|>":
        value = 1.3
    elif word == "not":
        if previous in DO_FORMS:
            value = 0.0
        elif previous in MODALS:
            value = 0.3
        else:
            value = 1.0 if spaced else 2.0
    elif RIME.fullmatch(word):
        value = 3.0 if spaced else 4.5
    elif "ot" in word and "oth" not in word:
        value = 0.5
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""Lexical 'well' detector, including comparative and translated forms.

'Well' gives the largest negative response, even as part of a name. The
fixed phrase 'as well' is weaker than other uses. Smaller responses mark
quality-of-performance words and translations of 'well' or 'good'.
The spelling fragment 'ell' and conversation markers (hello, hmm) also
give smaller negative responses.
Values are approximate activation levels fitted to training text.
All other tokens receive zero; previous-token rules stop at document borders.
"""
READS: tuple[str, ...] = ()

# Words describing the manner or quality of doing something.
MANNER = {
    'nicely': -2.5, 'easily': -1.0, 'beautifully': -1.0,
    'ideally': -0.9,
    'clearly': -0.83, 'perfectly': -0.77, 'effectively': -0.67,
    'readily': -0.68, 'thoroughly': -0.47, 'properly': -0.34,
    'correctly': -0.26, 'fully': -0.34, 'poorly': -3.25,
    'badly': -1.5, 'worse': -0.69, 'fine': -0.39,
}
# Multilingual lexical counterparts of well/good/better.
TRANSLATIONS = {
    'bien': -2.0, 'bem': -1.9, 'wohl': -0.71, 'wel': -0.7,
    'mieux': -2.0, 'melhor': -1.4, 'хорошо': -3.2,
    'лучше': -1.05,
    'よく': -2.05, '良く': -1.6, '잘': -3.0,
    '井': -6.1,  # The Chinese character for a water well.
}
# Chinese quality appraisals, not unrelated compounds such as '好奇' (curious).
GOOD_APPRAISALS = frozenset({
    '好的', '良好', '不好', '最好', '很好', '好了', '比较好',
    '还好', '挺好', '不太好', '非常好', '更好地', '很好地',
})
QUALIFIED_GOOD = frozenset({
    '最好的', '更好的', '良好的', '很好的', '做好', '的好',
    '就好', '也好', '更好', '的良好', '得好',
})
COPULAS = frozenset({'is', 'are', 'was', 'were', 'be', 'been'})


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    previous = ''
    if (prefix.position and
            prefix.document_ids[-1] == prefix.document_ids[-2]):
        previous = prefix.token_strings[-2].strip().lower()

    if word == 'well':
        if not token.startswith(' '):
            value = -5.4
        elif previous == 'as':
            value = -6.0
        elif previous in {'may', 'could', 'might'}:
            value = -6.1
        elif previous in COPULAS:
            value = -8.2
        else:
            value = -7.65
    elif word == 'Well':
        value = -6.9 if token.startswith(' ') else -6.8
    elif lower == 'wells':
        value = -2.3 if word == 'Wells' else -4.65
    elif lower in {'“well', '"well'}:
        value = -5.1
    elif lower in {'wellness', 'wellbeing'}:
        value = -1.7
    elif lower == 'better':
        value = -1.97 if token == ' better' else -1.5
    elif lower == 'best':
        value = -1.24 if token == ' best' else -0.81 if word == 'best' else -0.99
    elif lower == 'ill':
        value = -2.65 if token == ' ill' else -1.65 if word == 'Ill' else -0.23
    elif word in TRANSLATIONS:
        value = TRANSLATIONS[word]
    elif lower == 'bien':
        value = -1.6
    elif word == '好':
        value = -2.1
    elif word in GOOD_APPRAISALS:
        value = -1.8
    elif word in QUALIFIED_GOOD:
        value = -1.25
    elif lower in {'ell', 'ells'}:
        if previous.endswith('w'):
            value = -2.3 if previous[:-1].isalpha() else -4.5
        else:
            value = -0.45
    elif lower in MANNER:
        value = MANNER[lower]
    elif lower in {'hello', 'hell'}:
        value = -1.0 if lower == 'hello' else -0.6
    elif word == '嗯':
        value = -2.7
    elif lower in {'hmm', 'okay'}:
        value = -0.64 if lower == 'hmm' else -0.5
    else:
        value = 0.0
    return None, value

programs.haiku:
"""Layer-0 MLP down-projection component 5817: a 'well / good / better' detector.

It goes strongly negative on the English adverb "well" (most of its variance): about -7
on "well" in most uses (e.g. "going well", "well known", "as well"), and about -6 when the
word follows "as" or "Oh" ("as well as", "Oh well"). Weaker negatives come on the
comparatives "better" (-2) and "best" (-1.2), on "bien" and "好" (the "good/well" words
of French and Chinese), on "井" (the character for a well), and on manner adverbs such as
"easily", "clearly", "perfectly", "badly" (about -0.9). Everything else is about 0.
"""
READS = ()

WEAK_BEFORE = {"as", "oh"}          # "as well", "Oh well": the weaker "well"
VALUES = {
    "better": -2.0,
    "best": -1.2,
    "bien": -2.0,
    "好": -2.2,
    "井": -5.7,
}
MANNER = {"easily", "clearly", "perfectly", "badly", "poorly", "beautifully", "effectively", "ideally"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word == "well":
        previous = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
        return carry, (-5.9 if previous in WEAK_BEFORE else -7.2)
    if word in MANNER:
        return carry, -0.9
    return carry, VALUES.get(word, 0.0)

programs.sol:
"""A token-spelling detector dominated by ash, with weaker vowel+sh forms.

The table describes spelling families, not token identities.  Its columns
count letters before the cluster; beyond two, the response decays.
Common suffixes retain more activation than other continuations.  Capital
letters and leading whitespace weaken ash without preceding letters.  Short Cyrillic sha,
Arabic shin and Latin sibilant spellings have weaker parallel responses.
Context and differences between individual words are deliberately omitted.
"""

READS = ()

# Strengths for zero, one, or two letters before a vowel-sh cluster.
VOWEL_SH = {
    'ash': (7.05, 4.69, 3.38),
    'ush': (1.87, 1.28, 2.35),
    'ish': (0.98, 0.65, 0.32),
    'esh': (1.99, 1.73, 1.29),
    'osh': (2.28, 1.54, 0.71),
}
COMMON_SUFFIXES = {'ed', 'es', 'ing', 'er', 'ers'}


def spelling(text):
    word = text.strip()
    lower = word.lower()
    for cluster, strengths in VOWEL_SH.items():
        at = lower.find(cluster)
        if at < 0:
            continue
        before = sum(c.isalpha() for c in lower[:at])
        after = lower[at + 3:]
        value = strengths[min(before, 2)] * 0.64 ** max(0, before - 2)
        if after in COMMON_SUFFIXES:
            value *= 0.78
        elif after:
            value *= 0.22 if after[0] in 'aeiouy' else 0.26
        if cluster == 'ash' and before == 0:
            if word[at:at + 3] != 'ash':
                value *= 0.80
            if text[:1].isspace():
                value *= 0.81
        return value
    if 'sh' in lower:
        if lower == 'sh':
            return 0.70
        if lower == '/sh':
            return 1.90
        if lower == 'sha':
            return 1.05
        return 0.10
    if 'ш' in lower:
        for cluster, value in [('аш', 3.0), ('еш', 2.1), ('уш', 0.72),
                               ('иш', 0.73), ('ош', 0.85)]:
            at = lower.find(cluster)
            if at >= 0:
                before = sum(c.isalpha() for c in lower[:at])
                after = lower[at + 2:]
                decay = 0.25 if cluster == 'аш' else 0.62
                return value * decay ** before * (0.18 if after else 1.0)
        return (0.38 if text[:1].isspace() else 0.67) / max(1, len(word))
    if 'ش' in lower:
        if lower == 'اش':
            return 2.5
        if lower.endswith('ش'):
            return 0.8 if not text[:1].isspace() else 0.3
        return 0.15
    if any(c in lower for c in 'šśş'):
        return 0.6 / max(1, len(word))
    return 0.0


def step(carry, prefix, upstream):
    return None, float(spelling(prefix.token_strings[-1]))

programs.luna:
"""Estimate the response to sh spellings, with extra weight for ash-like pieces."""

READS = ()
SH_SPELLINGS = ("sh", "ш", "ش", "š", "sch")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    folded = token.casefold()
    core = folded.strip()

    # The short 'ash' and 'bash' token pieces are especially strong examples.
    if core in {"ash", "bash"}:
        return None, 5.5
    if "ash" in folded and not core.startswith("hash"):
        return None, 3.0
    if any(mark in folded for mark in SH_SPELLINGS):
        return None, 0.9

    # Also recognize an English digraph split between two adjacent tokens.
    if prefix.position:
        previous = prefix.token_strings[-2].casefold()
        same_document = (
            prefix.document_ids[-1] == prefix.document_ids[-2]
        )
        if same_document and previous.endswith("s") and folded.startswith("h"):
            return None, 0.9
    return None, 0.0

programs.sol:
"""A spelling-boundary heuristic dominated by c-initial word fragments.

An unspaced c-initial piece responds negatively after letters, more weakly
after digits. Short pieces, especially c before labial letters or g, are
strongest; ch/ck and longer pieces are weaker. Case and the preceding piece's
length adjust the strength. Short consonant-initial, c-final pieces give a
smaller positive response; g/k-initial pieces respond weakly. Non-Latin
current tokens and finer lexical distinctions are left unmodeled.
"""
READS = ()
VOWELS = frozenset('aeiou')
LABIALS = frozenset('bmpfv')
C_SUFFIXES = frozenset(('cation', 'cations', 'cular', 'cularly'))


def c_strength(word):
    text, n = word.lower(), len(word)
    if n == 1:
        return 0.42 if word.islower() else 0.20
    if text.startswith(('ch', 'ck')):
        return 0.12
    if text.startswith('cc'):
        return 0.40 if n == 2 else 0.15
    if n == 2:
        if text[1] in LABIALS or text[1] == 'g':
            return 1.85
        if text[1] not in VOWELS:
            return 0.90
        strength = 0.20 if text[1] == 'e' else 0.70 if text[1] == 'u' else 0.40
        return strength * (1.8 if word.isupper() else 1.0)
    strength = 0.75 if n == 3 else 0.44 if n == 4 else 0.20
    if text[-1] == 's':
        strength *= 0.6
    return 0.95 if text in C_SUFFIXES else strength


def response(token, previous):
    word = token.lstrip()
    if not word or not word.isascii() or not word.isalpha():
        return 0.0
    text, n = word.lower(), len(word)
    adjacent = token == word and bool(previous)
    joined = adjacent and previous[-1].isalpha()
    digit_join = adjacent and previous[-1].isdigit()
    if text[0] == 'c':
        if not (joined or digit_join):
            if n == 2 and (text[1] in LABIALS or text[1] == 'g'):
                return -0.25
            return 0.05 if n == 1 else 0.0
        strength = c_strength(word)
        if n > 1 and word[0].isupper() and not word.isupper():
            strength *= 0.45
        if digit_join:
            return -strength * (0.3 if n == 1 else 0.45)
        if previous[-1].lower() == 'c':
            strength = max(0.0, strength - 0.35)
        length = len(previous.strip())
        if length >= 4:
            strength *= max(0.5, (3.0 / length) ** 0.5)
        elif length == 1:
            strength *= 1.2
        if previous[-1].lower() in 'ei':
            strength *= 0.2 if n == 1 else 0.7
        if previous[-1].isupper() and not word.isupper():
            strength *= 1.25
        elif word.isupper() and not previous[-1].isupper():
            strength *= 0.65
        return -strength
    if joined and text[0] in 'gk' and n > 1:
        if word.isupper() and n <= 3:
            return -0.30
        if n <= 3 and text[1] not in 'aeios':
            return -0.20
    if joined and text[-1] == 'c' and n <= 4:
        if text[0] in VOWELS:
            return 0.0
        return 0.50 if word.isupper() else 0.20
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    return (doc, token), response(token, previous)

programs.luna:
"""Recognize a few rare text contexts where the component has large spikes."""
READS = ()

def step(carry, prefix, upstream):
    """Track a short same-document text tail and match distinctive fragments."""
    doc = int(prefix.document_ids[-1])
    tail = carry[1] if carry is not None and carry[0] == doc else ""
    token = prefix.token_strings[-1]
    text = tail + token
    value = -0.00111
    if text.endswith("bits/stdc"):
        value = 0.70
    elif "MatrixMode" in token and text.endswith("glMatrixMode"):
        value = -0.84
    elif text.endswith("大尺度"):
        value = 0.60
    elif "createParallelGroup" in token and "layout" in tail.lower():
        value = -0.85
    elif token == ".ncbi" and "https://www" in tail.lower():
        value = -0.85
    elif token == "ecake" and tail.lower().endswith("chees"):
        value = -0.66
    return (doc, text[-120:]), value

programs.sol:
"""Signed signals at chat, thinking, and tool boundaries.

Blank lines after thinking tags and the closing tool-call marker are strongly
positive; chat/thinking openings are negative. Message endings depend on whether they
close a tool wrapper or follow sentence punctuation. A user header at the start
of a document is stronger than later headers. Ordinary text is background zero.
"""
READS = ()

TAG_VALUES = {
    '<|im_start|>': -0.083,
    '<think>': -0.158,
    '</think>': 0.012,
    '<tool_call>': 0.036,
    '</tool_call>': 0.243,
    '<tool_response>': 0.074,
    '</tool_response>': 0.107,
}
BLANK_LINE_AFTER = {
    '<think>': 0.273,
    '</think>': 0.344,
    '<tool_response>': 0.17,
}
TOOL_ENDS = frozenset(('</tool_call>', '</tool_response>'))
SENTENCE_ENDS = frozenset('.?!。！？')


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        position, previous = 0, ''
    else:
        position, previous = carry[1], carry[2]
    token = prefix.token_strings[-1]
    value = TAG_VALUES.get(token, 0.0)
    if token == '\n\n':
        value = BLANK_LINE_AFTER.get(previous, 0.009)
    elif token == '\n':
        if previous == 'assistant':
            value = 0.097
        elif previous in ('<tool_call>', '<tool_response>'):
            value = 0.069
        else:
            value = -0.005
    elif token == '<|im_end|>':
        if previous in TOOL_ENDS:
            value = -0.067
        elif previous[-1:] in SENTENCE_ENDS:
            value = 0.075
        else:
            value = 0.013
    elif previous == '<|im_start|>':
        if token == 'user' and position == 1:
            value = 0.154
        else:
            value = 0.017
    return (document, position + 1, token), float(value)

programs.haiku:
"""Draft 3: words for feeling and for the craft of storytelling.

Fires on English and Chinese words that talk about how a piece of writing, film or
music feels and how it is made: feel/feeling/emotion/mood/atmosphere, tension, and
technique words such as 手法, 表达, 情感, 节奏. Weaker on story/narrative-quality nouns
(story, language, quality, theme, detail, voice). Predicts 0 everywhere else.
"""

READS = ()

FEELING = {"feel", "feels", "feeling", "feelings", "felt", "emotion", "emotional",
           "emotions", "mood", "atmosphere", "tension", "suspense", "sense", "throughout",
           "moment", "moments", "heartfelt", "subtle", "memorable", "poignant"}
CRAFT = {"story", "stories", "narrative", "language", "quality", "theme", "themes",
         "detail", "details", "voice", "depth", "twist", "journey", "scenes", "tone",
         "photography", "acting", "moment", "element", "elements", "conflict"}
CHINESE_STRONG = {"手法", "表达", "表现", "技巧", "技法", "情感", "感情", "情绪", "感染",
                  "感觉", "节奏", "台词", "起伏", "回味", "饱满", "动人", "感"}
CHINESE_WEAK = {"语言", "题材", "塑造", "口感", "人物", "剧情", "故事", "风格", "意境", "情节"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in CHINESE_STRONG or word in FEELING:
        return None, 0.8
    if word in CHINESE_WEAK or word in CRAFT:
        return None, 0.4
    return None, 0.0
